/* Banco de questões — parte 2 (ampliação alinhada ao conteúdo programático do edital 01/2026 SSPREV, cargo 202).
   Mesmo formato de questions.js. Campos extras opcionais: texto (passagem de apoio), src (fonte, quando é questão real de prova), o com 5 itens quando a prova original tinha A-E. */
(() => {
  const Q2 = [
    // ================= CONTABILIDADE GERAL: partidas dobradas, PL, devedores duvidosos, operações financeiras, reservas/provisões, depreciação =================
    { t: 'cgeral', q: 'Pelo método das partidas dobradas, a compra de um veículo a prazo (financiado) para uso da empresa gera o seguinte lançamento:', o: ['débito em Veículos e crédito em Caixa.', 'débito em Veículos e crédito em Financiamentos a Pagar.', 'débito em Financiamentos a Pagar e crédito em Veículos.', 'débito em Despesa com Veículos e crédito em Caixa.'], a: 1, e: 'Entra um bem no ativo (débito em Veículos) e nasce uma obrigação no passivo (crédito em Financiamentos a Pagar). Não há saída de caixa nem despesa.' },
    { t: 'cgeral', q: 'O recebimento em dinheiro de uma duplicata de cliente, pelo valor de face, provoca:', o: ['aumento do ativo total.', 'redução do ativo total.', 'permuta entre contas do ativo, sem alterar o total.', 'aumento do patrimônio líquido.'], a: 2, e: 'Caixa aumenta e Duplicatas a Receber diminui no mesmo valor: fato permutativo dentro do ativo.' },
    { t: 'cgeral', q: 'A conta "Capital Social" tem natureza:', o: ['devedora, por ser um direito dos sócios.', 'credora, por integrar o patrimônio líquido.', 'devedora, por representar o dinheiro aplicado.', 'mista, variando conforme o resultado.'], a: 1, e: 'Contas de patrimônio líquido têm natureza credora: aumentam a crédito e diminuem a débito.' },
    { t: 'cgeral', q: 'Em um razonete da conta Caixa, os lançamentos a débito representam:', o: ['saídas de dinheiro.', 'entradas de dinheiro.', 'despesas pagas.', 'obrigações assumidas.'], a: 1, e: 'Caixa é conta de ativo: débito = aumento = entrada de dinheiro; crédito = saída.' },
    { t: 'cgeral', q: 'Uma empresa apurou lucro líquido de R$ 80.000 no exercício e não distribuiu dividendos. O efeito sobre o patrimônio líquido é:', o: ['aumento de R$ 80.000.', 'redução de R$ 80.000.', 'nenhum, pois lucro é conta de resultado.', 'aumento apenas do ativo circulante.'], a: 0, e: 'O lucro apurado é transferido para o PL (lucros acumulados/reservas), aumentando-o. É um fato modificativo aumentativo acumulado ao longo do período.' },
    { t: 'cgeral', q: 'Se o Ativo é R$ 300.000 e o Patrimônio Líquido é R$ 120.000, o Passivo exigível é:', o: ['R$ 420.000.', 'R$ 180.000.', 'R$ 120.000.', 'R$ 300.000.'], a: 1, e: 'Passivo = Ativo − PL = 300.000 − 120.000 = 180.000.' },
    { t: 'cgeral', q: 'A apropriação da despesa de aluguel do mês, ainda não paga, é um fato contábil:', o: ['permutativo, pois só envolve contas patrimoniais.', 'modificativo diminutivo, pois reduz o PL e cria uma obrigação.', 'modificativo aumentativo.', 'misto aumentativo.'], a: 1, e: 'Reconhece-se a despesa (reduz o PL) contra Aluguéis a Pagar (passivo). Nenhuma permuta ocorre: modificativo diminutivo.' },
    { t: 'cgeral', q: 'O pagamento de uma dívida de R$ 10.000 com desconto de R$ 500 obtido por pontualidade caracteriza fato:', o: ['permutativo.', 'modificativo diminutivo.', 'misto aumentativo.', 'misto diminutivo.'], a: 2, e: 'Há permuta (reduz passivo e caixa) e um ganho de R$ 500 (desconto obtido), que aumenta o PL: misto aumentativo.' },
    { t: 'cgeral', q: 'Ao constituir a Perda Estimada em Créditos de Liquidação Duvidosa (PECLD), a empresa:', o: ['debita Clientes e credita Caixa.', 'debita uma despesa e credita a conta redutora de Clientes.', 'debita Clientes e credita Receita.', 'debita a conta redutora e credita Despesa.'], a: 1, e: 'Lançamento: D Despesa com PECLD / C PECLD (redutora do ativo). O ativo líquido realizável diminui e o resultado é afetado.' },
    { t: 'cgeral', q: 'Quando um cliente cuja dívida já estava coberta pela PECLD é definitivamente considerado incobrável, a baixa do título é feita:', o: ['contra a conta de despesa do período.', 'contra a conta PECLD, sem afetar o resultado do período.', 'contra receita financeira.', 'contra o capital social.'], a: 1, e: 'A perda já foi reconhecida quando a estimativa foi constituída. A baixa é D PECLD / C Clientes, sem novo efeito no resultado.' },
    { t: 'cgeral', q: 'Clientes de R$ 200.000 e PECLD de R$ 6.000. O valor líquido realizável de Clientes apresentado no balanço é:', o: ['R$ 206.000.', 'R$ 200.000.', 'R$ 194.000.', 'R$ 6.000.'], a: 2, e: 'A redutora é apresentada abaixo da conta principal: 200.000 − 6.000 = 194.000.' },
    { t: 'cgeral', q: 'No desconto de uma nota promissória de R$ 10.000 com juros antecipados de R$ 800, o valor líquido recebido pela empresa e o tratamento dos juros são, respectivamente:', o: ['R$ 10.000; juros como receita.', 'R$ 9.200; juros apropriados como despesa financeira ao longo do prazo.', 'R$ 9.200; juros lançados como despesa integral no recebimento.', 'R$ 10.800; juros como passivo.'], a: 1, e: 'Recebe 9.200. A obrigação com o banco é de 10.000; os 800 ficam em "Encargos financeiros a apropriar" (redutora do passivo) e viram despesa pelo regime de competência.' },
    { t: 'cgeral', q: 'Uma aplicação financeira de renda fixa feita pela empresa é classificada no balanço como:', o: ['passivo circulante.', 'ativo (circulante ou não circulante, conforme o prazo de resgate).', 'patrimônio líquido.', 'despesa antecipada.'], a: 1, e: 'Aplicações financeiras são direitos da empresa: ativo. Os rendimentos apropriados pela competência são receita financeira.' },
    { t: 'cgeral', q: 'Em um empréstimo pré-fixado, à medida que o tempo passa, os juros a apropriar:', o: ['aumentam o passivo total.', 'são transferidos para despesa financeira, aumentando o passivo líquido exigível.', 'são lançados como receita.', 'permanecem inalterados até o vencimento.'], a: 1, e: 'A cada mês: D Despesa Financeira / C Juros a Apropriar. A redutora diminui e o passivo líquido cresce até atingir o valor a pagar no vencimento.' },
    { t: 'cgeral', q: 'A duplicata descontada em banco, enquanto não liquidada pelo cliente, representa para a empresa:', o: ['uma receita realizada.', 'uma obrigação (passivo), pois a empresa responde pelo pagamento se o cliente não pagar.', 'um ativo adicional.', 'uma redução do capital social.'], a: 1, e: 'No desconto, a empresa recebe antecipadamente mas continua coobrigada: registra-se um passivo (Duplicatas Descontadas) até a liquidação.' },
    { t: 'cgeral', q: 'A Reserva Legal é constituída com:', o: ['parte do lucro líquido do exercício, até os limites legais.', 'ágio na emissão de ações.', 'valores de clientes em atraso.', 'provisão para férias.'], a: 0, e: 'Reserva legal: 5% do lucro líquido, até 20% do capital social (Lei 6.404). É reserva de LUCROS, integra o PL.' },
    { t: 'cgeral', q: 'A "Provisão para Férias" e a "Provisão para 13º salário" são classificadas como:', o: ['reservas do patrimônio líquido.', 'contas redutoras do ativo.', 'passivos, por representarem obrigações já incorridas com os empregados.', 'receitas diferidas.'], a: 2, e: 'São obrigações decorrentes de serviços já prestados pelos empregados, registradas pelo regime de competência no passivo, com contrapartida em despesa.' },
    { t: 'cgeral', q: 'Assinale a alternativa que contém apenas contas do patrimônio líquido:', o: ['Capital Social, Reserva Legal, Reservas de Lucros.', 'Capital Social, Provisão para Contingências, Fornecedores.', 'Reserva Legal, Depreciação Acumulada, Caixa.', 'Lucros Acumulados, PECLD, Empréstimos.'], a: 0, e: 'Provisões e fornecedores são passivo; depreciação acumulada e PECLD são redutoras do ativo.' },
    { t: 'cgeral', q: 'Um equipamento custou R$ 120.000, tem vida útil estimada de 10 anos e valor residual de R$ 20.000. Após 3 anos de uso, o valor contábil líquido pelo método linear é:', o: ['R$ 90.000.', 'R$ 84.000.', 'R$ 100.000.', 'R$ 30.000.'], a: 0, e: 'Depreciação anual = (120.000 − 20.000)/10 = 10.000. Acumulada em 3 anos = 30.000. Valor contábil = 120.000 − 30.000 = 90.000.' },
    { t: 'cgeral', q: 'O registro da depreciação do período é feito por:', o: ['débito em Depreciação Acumulada e crédito em Despesa de Depreciação.', 'débito em Despesa de Depreciação e crédito em Depreciação Acumulada.', 'débito em Imobilizado e crédito em Caixa.', 'débito em Caixa e crédito em Imobilizado.'], a: 1, e: 'A despesa reduz o resultado; a acumulada (redutora) reduz o imobilizado. Não há movimentação de caixa.' },
    { t: 'cgeral', q: 'A amortização aplica-se a:', o: ['máquinas e veículos.', 'direitos com prazo de existência limitado, como softwares, marcas e patentes.', 'jazidas minerais.', 'terrenos.'], a: 1, e: 'Amortização: intangíveis de vida útil definida. Depreciação: tangíveis. Exaustão: recursos naturais.' },
    { t: 'cgeral', q: 'Uma empresa adquiriu direito de exploração de uma floresta por R$ 500.000, estimando extrair 100.000 m³ de madeira. Extraindo 20.000 m³ no ano, a exaustão do período é:', o: ['R$ 50.000.', 'R$ 100.000.', 'R$ 20.000.', 'R$ 500.000.'], a: 1, e: 'Exaustão pelo método das unidades extraídas: 500.000 × (20.000/100.000) = 100.000.' },
    { t: 'cgeral', q: 'A depreciação de um bem começa a ser registrada:', o: ['na data da compra, mesmo que o bem ainda não esteja em uso.', 'quando o bem está disponível para uso, no local e condição necessários para operar.', 'somente no encerramento do exercício.', 'quando o bem é vendido.'], a: 1, e: 'Pelas normas contábeis (CPC 27), a depreciação inicia quando o ativo está disponível para uso.' },

    // ================= CONTABILIDADE PÚBLICA: sistemas, orçamento =================
    { t: 'cpub', q: 'As garantias recebidas de fornecedores e os contratos assinados pela Administração, que podem vir a afetar o patrimônio, são registrados em contas de:', o: ['natureza patrimonial, no ativo.', 'compensação (atos potenciais).', 'resultado, como despesa.', 'receita extraorçamentária.'], a: 1, e: 'Atos potenciais (ativos e passivos) ficam no sistema/subsistema de compensação até se converterem em fatos.' },
    { t: 'cpub', q: 'Segundo o MCASP, a contabilidade aplicada ao setor público estrutura-se em subsistemas de informações. Assinale o que NÃO é um deles:', o: ['orçamentário.', 'patrimonial.', 'de custos.', 'tributário.'], a: 3, e: 'Subsistemas do MCASP: orçamentário, patrimonial, de custos e de compensação. A Lei 4.320 fala em sistemas orçamentário, financeiro, patrimonial e de compensação.' },
    { t: 'cpub', q: 'O sistema (subsistema) orçamentário registra:', o: ['a previsão da receita, a fixação da despesa e sua execução (empenho, liquidação, pagamento, arrecadação).', 'apenas os bens móveis e imóveis.', 'os atos potenciais.', 'as variações patrimoniais qualitativas.'], a: 0, e: 'O subsistema orçamentário acompanha o orçamento aprovado e sua execução: previsão/fixação, créditos adicionais, empenho, liquidação, pagamento e arrecadação.' },
    { t: 'cpub', q: 'O princípio orçamentário da UNIDADE (ou totalidade) determina que:', o: ['cada ente tenha um único orçamento, reunindo todas as receitas e despesas.', 'a receita seja classificada por fonte.', 'o orçamento vigore por quatro anos.', 'as despesas sejam fixadas pelo Legislativo.'], a: 0, e: 'Unidade: um só orçamento por ente e exercício (na CF, a LOA compreende os orçamentos fiscal, da seguridade e de investimento, mas é uma só lei).' },
    { t: 'cpub', q: 'O princípio da UNIVERSALIDADE estabelece que:', o: ['o orçamento deve conter todas as receitas e todas as despesas do ente.', 'o orçamento só contém despesas obrigatórias.', 'as receitas podem ficar fora do orçamento se forem vinculadas.', 'o orçamento deve ser aprovado por unanimidade.'], a: 0, e: 'Universalidade: todas as receitas e despesas integram o orçamento (art. 3º e 4º da Lei 4.320).' },
    { t: 'cpub', q: 'O princípio do EQUILÍBRIO orçamentário significa que:', o: ['a despesa fixada não deve ultrapassar a receita prevista.', 'todas as despesas devem ser iguais entre os órgãos.', 'o orçamento deve ser dividido igualmente entre os Poderes.', 'as receitas correntes devem ser iguais às de capital.'], a: 0, e: 'Equilíbrio: receita prevista = despesa fixada. A LRF reforça com a regra de ouro e metas de resultado.' },
    { t: 'cpub', q: 'Pelo princípio da ESPECIFICAÇÃO (ou discriminação), é vedado(a):', o: ['a inclusão de dotações globais para atender indiferentemente a despesas, salvo programas especiais e reserva de contingência.', 'a vinculação de receita de impostos.', 'a abertura de créditos suplementares.', 'o remanejamento entre categorias econômicas.'], a: 0, e: 'Art. 5º da Lei 4.320: a LOA não consignará dotações globais destinadas a atender indiferentemente a despesas de pessoal, material, serviços, transferências e obras.' },
    { t: 'cpub', q: 'A Lei Orçamentária Anual (LOA) compreende, segundo a Constituição:', o: ['o orçamento fiscal, o orçamento de investimento das estatais e o orçamento da seguridade social.', 'apenas o orçamento fiscal.', 'o PPA e a LDO.', 'o orçamento da União e dos Estados.'], a: 0, e: 'CF art. 165, §5º: três orçamentos em uma única lei (fiscal, investimento das empresas estatais e seguridade social).' },
    { t: 'cpub', q: 'Quanto à iniciativa e à aprovação, as leis orçamentárias (PPA, LDO e LOA):', o: ['são de iniciativa do Poder Legislativo e aprovadas por decreto.', 'são de iniciativa privativa do Chefe do Poder Executivo e aprovadas pelo Poder Legislativo.', 'são de iniciativa do Tribunal de Contas.', 'dispensam aprovação legislativa.'], a: 1, e: 'CF art. 165: leis de iniciativa do Poder Executivo, votadas pelo Legislativo. No município, o Prefeito envia e a Câmara aprova.' },
    { t: 'cpub', q: 'O ciclo orçamentário compreende, em ordem, as fases de:', o: ['execução, elaboração, aprovação e controle.', 'elaboração, aprovação (apreciação legislativa), execução e controle/avaliação.', 'aprovação, controle, execução e elaboração.', 'controle, execução, elaboração e aprovação.'], a: 1, e: 'Elabora-se a proposta (Executivo), aprova-se (Legislativo), executa-se (exercício) e controla-se/avalia-se (interno e externo).' },
    { t: 'cpub', q: 'A LDO deve, entre outras funções:', o: ['dispor sobre as alterações na legislação tributária e orientar a elaboração da LOA.', 'fixar o valor das despesas de cada unidade orçamentária.', 'autorizar operações de crédito por antecipação de receita.', 'substituir o PPA nos anos de eleição.'], a: 0, e: 'CF art. 165, §2º: a LDO compreende metas e prioridades, orienta a elaboração da LOA, dispõe sobre alterações tributárias e política das agências de fomento.' },
    { t: 'cpub', q: 'Caso a LOA não seja aprovada até o início do exercício, a solução usualmente prevista na LDO é:', o: ['suspender todos os pagamentos.', 'executar a proposta orçamentária em duodécimos (1/12 por mês) até a aprovação.', 'o Executivo aprovar o orçamento por decreto.', 'repetir o orçamento de quatro anos atrás.'], a: 1, e: 'A LDO costuma autorizar a execução provisória por duodécimos para despesas continuadas enquanto a LOA não é sancionada.' },

    // ================= RECEITA PÚBLICA =================
    { t: 'cpub', q: 'Receita orçamentária é aquela que:', o: ['transita pelo caixa mas pertence a terceiros.', 'pertence ao ente público, integra o orçamento e pode financiar despesas.', 'depende sempre de autorização do Tribunal de Contas.', 'é devolvida ao final do exercício.'], a: 1, e: 'Receita orçamentária é fonte de recursos do ente (previsão na LOA). Extraorçamentária: ingressos de terceiros, transitórios (cauções, consignações).' },
    { t: 'cpub', q: 'Os valores descontados na folha dos servidores a título de consignação (ex.: empréstimo consignado) e repassados posteriormente aos credores são, para o ente:', o: ['receita tributária.', 'receita de capital.', 'receita extraorçamentária (ingresso de terceiros).', 'receita de contribuições.'], a: 2, e: 'Consignações são valores de terceiros em trânsito: entram como receita extraorçamentária e saem como despesa extraorçamentária.' },
    { t: 'cpub', q: 'A inscrição de Restos a Pagar no encerramento do exercício é tratada, no Balanço Financeiro, como:', o: ['despesa orçamentária.', 'receita extraorçamentária, para compensar a despesa orçamentária empenhada e não paga.', 'receita de capital.', 'variação patrimonial diminutiva.'], a: 1, e: 'Art. 103, parágrafo único, da Lei 4.320: os RP do exercício são computados na receita extraorçamentária.' },
    { t: 'cpub', q: 'A receita de "Contribuições" (categoria corrente) inclui, no caso de um RPPS municipal:', o: ['os impostos municipais.', 'as contribuições previdenciárias dos servidores e a contribuição patronal do ente.', 'a alienação de imóveis.', 'as operações de crédito.'], a: 1, e: 'Receita de contribuições: sociais (previdenciárias), de intervenção no domínio econômico e de interesse de categorias. Para o RPPS, a principal fonte.' },
    { t: 'cpub', q: 'A receita decorrente de aluguéis de imóveis públicos e de rendimentos de aplicações financeiras é classificada como:', o: ['receita patrimonial.', 'receita tributária.', 'receita de serviços.', 'receita de capital.'], a: 0, e: 'Receita patrimonial: resultado da exploração do patrimônio (aluguéis, juros, dividendos, rendimentos de aplicações).' },
    { t: 'cpub', q: 'As transferências recebidas de outro ente destinadas a despesas de capital (ex.: convênio para construir uma escola) são:', o: ['transferências correntes.', 'transferências de capital.', 'operações de crédito.', 'receita de serviços.'], a: 1, e: 'Transferências de capital financiam investimentos; transferências correntes financiam despesas correntes (ex.: FPM, cota do ICMS).' },
    { t: 'cpub', q: 'A "amortização de empréstimos" concedidos pelo ente a terceiros, quando recebida, é:', o: ['receita corrente de serviços.', 'receita de capital.', 'despesa de capital.', 'receita extraorçamentária.'], a: 1, e: 'Art. 11 da Lei 4.320: amortização de empréstimos é receita de capital (retorno do principal emprestado).' },
    { t: 'cpub', q: 'O estágio da receita que consiste na estimativa constante da LOA é denominado:', o: ['lançamento.', 'arrecadação.', 'previsão.', 'recolhimento.'], a: 2, e: 'Previsão (planejamento) → lançamento → arrecadação → recolhimento (execução).' },
    { t: 'cpub', q: 'Nem toda receita passa pelo estágio do lançamento. Exemplo de receita que normalmente NÃO é lançada:', o: ['IPTU.', 'ISS lançado de ofício.', 'receita de serviços pagos no balcão e doações espontâneas.', 'contribuição de melhoria.'], a: 2, e: 'O lançamento aplica-se a receitas com contribuinte identificável e valor apurado previamente (tributos lançados). Receitas eventuais são arrecadadas diretamente.' },
    { t: 'cpub', q: 'A "quitação" de uma receita pública corresponde ao momento em que:', o: ['o orçamento é aprovado.', 'o contribuinte paga e recebe comprovante de quitação do débito, extinguindo a obrigação.', 'o Tesouro transfere o valor ao banco.', 'a dívida ativa é inscrita.'], a: 1, e: 'Quitação é a comprovação do pagamento ao contribuinte (recibo/comprovante), associada ao estágio da arrecadação.' },
    { t: 'cpub', q: 'Os "resíduos ativos" ou "restos a arrecadar" correspondem a:', o: ['receitas lançadas e não arrecadadas no exercício.', 'despesas empenhadas e não pagas.', 'saldos bancários disponíveis.', 'créditos adicionais não utilizados.'], a: 0, e: 'Receita lançada e não arrecadada até 31/12 não é receita do exercício (regime de caixa); os créditos vencidos são inscritos em dívida ativa.' },
    { t: 'cpub', q: 'A inscrição de um crédito em Dívida Ativa:', o: ['é uma receita orçamentária do exercício.', 'é um fato permutativo no patrimônio: o crédito a receber muda de classificação, não há receita orçamentária até que seja arrecadado.', 'extingue o crédito.', 'exige autorização legislativa específica.'], a: 1, e: 'A inscrição apenas reclassifica o direito (crédito tributário → dívida ativa). A receita orçamentária só é reconhecida na arrecadação (recebimento da dívida ativa).' },
    { t: 'cpub', q: 'Multa de trânsito não paga, aluguel atrasado devido ao município e laudêmio são créditos que, inscritos, constituem:', o: ['dívida ativa tributária.', 'dívida ativa não tributária.', 'restos a pagar.', 'dívida fundada.'], a: 1, e: 'Art. 39, §2º: dívida ativa não tributária inclui multas não tributárias, foros, laudêmios, aluguéis, indenizações, reposições, etc.' },
    { t: 'cpub', q: 'A restituição de um tributo pago indevidamente pelo contribuinte, quando efetuada no mesmo exercício da arrecadação, é tratada como:', o: ['despesa orçamentária de custeio.', 'dedução da receita orçamentária.', 'despesa extraorçamentária.', 'receita de capital negativa.'], a: 1, e: 'Pelo MCASP, restituições de receitas são registradas como dedução da receita (conta redutora), preservando a receita líquida arrecadada.' },
    { t: 'cpub', q: 'Receita originária e receita derivada distinguem-se porque:', o: ['a originária decorre do poder de império (tributos); a derivada, da exploração do patrimônio.', 'a originária decorre da exploração do próprio patrimônio do Estado (aluguéis, serviços); a derivada, do poder de império sobre o particular (tributos, multas).', 'a originária é extraorçamentária.', 'não há diferença prática.'], a: 1, e: 'Originária: Estado age como particular (patrimonial, serviços). Derivada: Estado impõe (tributos, multas, contribuições).' },

    // ================= DESPESA PÚBLICA =================
    { t: 'cpub', q: 'Despesa extraorçamentária é aquela que:', o: ['depende de autorização na LOA.', 'corresponde à saída de valores de terceiros que haviam ingressado como receita extraorçamentária, independendo de autorização orçamentária.', 'é paga com créditos adicionais.', 'só pode ocorrer em dezembro.'], a: 1, e: 'Ex.: devolução de caução, pagamento de restos a pagar, repasse de consignações. Não integra o orçamento.' },
    { t: 'cpub', q: 'O pagamento, no exercício atual, de Restos a Pagar inscritos no exercício anterior é classificado como:', o: ['despesa orçamentária do exercício atual.', 'despesa extraorçamentária.', 'despesa de exercícios anteriores (DEA).', 'crédito extraordinário.'], a: 1, e: 'A despesa já foi orçamentária no ano do empenho. O pagamento de RP é desembolso extraorçamentário.' },
    { t: 'cpub', q: 'Despesas com pessoal e encargos, material de consumo e serviços de terceiros, necessárias à manutenção dos órgãos, são classificadas como:', o: ['despesas de capital — investimentos.', 'despesas correntes — custeio.', 'inversões financeiras.', 'transferências de capital.'], a: 1, e: 'Despesas de custeio (art. 12, §1º): manutenção de serviços anteriormente criados, inclusive obras de conservação e adaptação.' },
    { t: 'cpub', q: 'Aposentadorias e pensões pagas pelo RPPS são, pela classificação da Lei 4.320/64, despesas:', o: ['de capital.', 'correntes — transferências correntes.', 'extraorçamentárias.', 'de investimento.'], a: 1, e: 'Transferências correntes: despesas sem contraprestação direta em bens ou serviços, inclusive inativos e pensionistas.' },
    { t: 'cpub', q: 'A amortização (pagamento do principal) da dívida pública é classificada como despesa:', o: ['corrente de custeio.', 'de capital.', 'extraorçamentária.', 'corrente de transferência.'], a: 1, e: 'Amortização da dívida é despesa de capital (grupo "amortização da dívida"). Os juros são despesa corrente.' },
    { t: 'cpub', q: 'A fase de FIXAÇÃO da despesa ocorre:', o: ['no pagamento ao credor.', 'na aprovação da LOA, que estabelece as dotações.', 'na emissão da nota de empenho.', 'na liquidação.'], a: 1, e: 'Fixação é a etapa de planejamento (dotação na LOA); empenho, liquidação e pagamento são a execução.' },
    { t: 'cpub', q: 'A Nota de Empenho deve indicar:', o: ['apenas o valor pago.', 'o nome do credor, a representação e a importância da despesa, bem como a dedução desta do saldo da dotação própria.', 'o resultado do balanço patrimonial.', 'o número do processo licitatório, somente.'], a: 1, e: 'Art. 61 da Lei 4.320.' },
    { t: 'cpub', q: 'É vedado o empenho de despesa:', o: ['em valor inferior a R$ 1.000.', 'que exceda o limite dos créditos concedidos (dotação disponível).', 'em dezembro.', 'para pessoal.'], a: 1, e: 'Art. 59 da Lei 4.320: o empenho não pode exceder o limite dos créditos concedidos.' },
    { t: 'cpub', q: 'A liquidação da despesa de uma compra de material é feita com base em:', o: ['estimativa do gestor.', 'contrato, nota de empenho e comprovantes da entrega do material (nota fiscal e atesto).', 'apenas na nota de empenho.', 'no balanço orçamentário.'], a: 1, e: 'Art. 63, §2º: a liquidação tem por base o contrato/ajuste, a nota de empenho e os comprovantes da entrega do material ou da prestação do serviço.' },
    { t: 'cpub', q: 'O ordenador de despesa determina o pagamento por meio de:', o: ['nota de empenho.', 'ordem de pagamento, despacho exarado por autoridade competente.', 'nota de lançamento da receita.', 'balancete.'], a: 1, e: 'Art. 64 da Lei 4.320: ordem de pagamento é o despacho que determina que a despesa seja paga.' },
    { t: 'cpub', q: 'Um contrato de aluguel de prédio por 12 meses, com pagamentos mensais, deve ser empenhado preferencialmente por empenho:', o: ['ordinário, um para cada mês.', 'global, abrangendo o valor total do contrato, com liquidações e pagamentos parciais.', 'estimativo, pois o valor é incerto.', 'extraordinário.'], a: 1, e: 'Empenho global: despesas contratuais sujeitas a parcelamento (art. 60, §3º).' },
    { t: 'cpub', q: 'Os Restos a Pagar NÃO PROCESSADOS podem ser:', o: ['pagos sem liquidação.', 'liquidados e pagos no exercício seguinte, ou cancelados se a condição não se cumprir.', 'convertidos em receita.', 'transferidos para o PPA.'], a: 1, e: 'RP não processados aguardam a liquidação (entrega do bem/serviço); se não houver, são cancelados.' },
    { t: 'cpub', q: 'Os "resíduos passivos" na terminologia da Lei 4.320/64 correspondem a:', o: ['restos a pagar.', 'dívida ativa.', 'créditos adicionais.', 'superávit financeiro.'], a: 0, e: 'Resíduos passivos = restos a pagar (despesas empenhadas e não pagas até 31/12).' },
    { t: 'cpub', q: 'Dívida fundada (ou consolidada) é aquela:', o: ['com exigibilidade inferior a 12 meses.', 'que compreende compromissos de exigibilidade superior a 12 meses, contraídos para atender desequilíbrio orçamentário ou financiamento de obras e serviços.', 'formada por depósitos e cauções.', 'que não precisa ser escriturada.'], a: 1, e: 'Art. 98 da Lei 4.320. A LRF (art. 29) define dívida consolidada de forma semelhante e inclui operações de crédito de prazo inferior a 12 meses cujas receitas constem do orçamento.' },
    { t: 'cpub', q: 'Compõem a dívida flutuante, EXCETO:', o: ['os depósitos.', 'os débitos de tesouraria (ARO).', 'os restos a pagar (excluídos os serviços da dívida).', 'os empréstimos de longo prazo para obras.'], a: 3, e: 'Empréstimos de longo prazo são dívida fundada. Dívida flutuante: RP, serviços da dívida a pagar, depósitos, débitos de tesouraria.' },
    { t: 'cpub', q: 'Uma despesa de 2025 que não foi empenhada em 2025 por falta de processamento, embora houvesse crédito próprio com saldo suficiente no orçamento daquele ano, poderá ser paga em 2026:', o: ['como restos a pagar de 2025.', 'à conta de dotação específica de Despesas de Exercícios Anteriores no orçamento de 2026.', 'por crédito extraordinário.', 'somente por decisão judicial.'], a: 1, e: 'Art. 37 da Lei 4.320: DEA, com dotação própria no orçamento vigente, obedecida a ordem cronológica.' },
    { t: 'cpub', q: 'Restos a pagar cuja prescrição foi interrompida e compromissos reconhecidos após o encerramento do exercício correspondente são pagos como:', o: ['despesas de exercícios anteriores.', 'despesas extraorçamentárias.', 'créditos suplementares.', 'dívida ativa.'], a: 0, e: 'São as outras duas hipóteses de DEA previstas no art. 37.' },

    // ================= REGIMES CONTÁBEIS, ADIANTAMENTO, PATRIMÔNIO =================
    { t: 'cpub', q: 'Para fins de apuração orçamentária, a Lei 4.320/64 adota para a receita o regime de:', o: ['competência.', 'caixa (arrecadação).', 'exercício misto.', 'competência atuarial.'], a: 1, e: 'Art. 35, I: pertencem ao exercício as receitas nele arrecadadas.' },
    { t: 'cpub', q: 'Para a despesa orçamentária, a Lei 4.320/64 adota o regime de:', o: ['caixa (pagamento).', 'competência, pelo empenho (despesas legalmente empenhadas no exercício).', 'competência, pela liquidação.', 'caixa, pela ordem de pagamento.'], a: 1, e: 'Art. 35, II: despesas nele legalmente empenhadas.' },
    { t: 'cpub', q: 'Sob a ótica PATRIMONIAL (MCASP), as variações patrimoniais aumentativas e diminutivas são reconhecidas:', o: ['pelo regime de caixa.', 'pelo regime de competência, independentemente da execução orçamentária.', 'somente quando empenhadas.', 'apenas no encerramento do exercício.'], a: 1, e: 'O MCASP separa o enfoque orçamentário (art. 35) do patrimonial, que segue a competência integral (ex.: depreciação, provisões, receita por fato gerador).' },
    { t: 'cpub', q: 'O regime de adiantamento (suprimento de fundos) é adequado para:', o: ['compras de grande vulto.', 'despesas de pequeno vulto, de caráter eventual ou que exijam pronto pagamento, que não possam subordinar-se ao processo normal de aplicação.', 'pagamento de folha de pessoal.', 'investimentos em obras.'], a: 1, e: 'Art. 68 da Lei 4.320: despesas expressamente definidas em lei que não possam seguir o processo normal.' },
    { t: 'cpub', q: 'Sobre o regime de adiantamento, é correto afirmar:', o: ['dispensa prestação de contas.', 'o servidor em alcance (que não prestou contas de adiantamento anterior) não pode receber novo adiantamento.', 'pode ser concedido a qualquer pessoa, inclusive a terceiros.', 'não exige empenho.'], a: 1, e: 'Art. 69: vedado a servidor em alcance e a responsável por dois adiantamentos. Sempre precedido de empenho e sujeito a prestação de contas.' },
    { t: 'cpub', q: 'Os Restos a Pagar processados, enquanto não pagos, integram o:', o: ['ativo financeiro.', 'passivo financeiro.', 'ativo permanente.', 'passivo permanente.'], a: 1, e: 'Passivo financeiro: compromissos exigíveis cujo pagamento independe de autorização orçamentária (RP, depósitos, serviço da dívida a pagar).' },
    { t: 'cpub', q: 'Os bens imóveis do município (prédios, terrenos) integram o:', o: ['ativo financeiro.', 'ativo permanente, pois sua alienação depende de autorização legislativa.', 'passivo permanente.', 'sistema de compensação.'], a: 1, e: 'Art. 105, §2º: ativo permanente compreende bens, créditos e valores cuja mobilização ou alienação dependa de autorização legislativa.' },
    { t: 'cpub', q: 'Ativo financeiro de R$ 800.000 e passivo financeiro de R$ 500.000 em 31/12. O superávit financeiro apurado é:', o: ['R$ 1.300.000.', 'R$ 300.000.', 'R$ 500.000.', 'déficit de R$ 300.000.'], a: 1, e: 'Superávit financeiro = AF − PF = 300.000. É fonte para abertura de créditos adicionais no exercício seguinte.' },
    { t: 'cpub', q: 'A dívida fundada do município integra o:', o: ['passivo financeiro.', 'passivo permanente.', 'ativo permanente.', 'ativo financeiro.'], a: 1, e: 'Passivo permanente: dívida fundada e outras que dependam de autorização legislativa para amortização ou resgate.' },
    { t: 'cpub', q: 'Pelo MCASP, os bens de uso comum do povo (praças, ruas), quando mensuráveis, devem ser:', o: ['excluídos da contabilidade.', 'registrados no ativo imobilizado e sujeitos a depreciação quando aplicável.', 'registrados como despesa corrente.', 'registrados apenas em contas de compensação.'], a: 1, e: 'O MCASP determina o reconhecimento dos bens de uso comum no imobilizado, sempre que puderem ser mensurados confiavelmente.' },

    // ================= CRÉDITOS ADICIONAIS =================
    { t: 'cpub', q: 'Um município precisa custear despesas de uma nova secretaria criada por lei em maio, sem dotação na LOA. O crédito adicional cabível é o:', o: ['suplementar.', 'especial.', 'extraordinário.', 'ordinário.'], a: 1, e: 'Especial: despesa para a qual não há dotação orçamentária específica. Requer lei autorizativa e decreto de abertura.' },
    { t: 'cpub', q: 'Enchentes atingem a cidade e o Prefeito precisa de recursos imediatos para abrigos. O instrumento é o crédito:', o: ['suplementar, autorizado na LOA.', 'especial, autorizado por lei.', 'extraordinário, aberto por decreto com imediato conhecimento ao Legislativo.', 'de antecipação de receita.'], a: 2, e: 'Extraordinário: despesas urgentes e imprevistas (guerra, comoção interna, calamidade pública), independe de prévia autorização legislativa e de indicação de fonte.' },
    { t: 'cpub', q: 'A autorização para abertura de créditos suplementares até certo limite (ex.: 20% da despesa fixada) costuma constar:', o: ['no PPA.', 'na própria LOA, como exceção ao princípio da exclusividade.', 'no RGF.', 'no balanço patrimonial.'], a: 1, e: 'CF art. 165, §8º e art. 7º da Lei 4.320: a LOA pode conter autorização para abertura de créditos suplementares.' },
    { t: 'cpub', q: 'Para abrir crédito suplementar usando "anulação parcial de dotação", a Administração:', o: ['cria nova receita.', 'remaneja recursos de uma dotação com sobra para reforçar outra, dentro do orçamento.', 'contrata empréstimo.', 'usa o superávit do exercício corrente.'], a: 1, e: 'A anulação de dotações é uma das fontes do art. 43, §1º: reduz uma dotação para suplementar outra.' },
    { t: 'cpub', q: 'Um crédito especial autorizado e aberto em novembro de 2026, com saldo não utilizado em 31/12/2026:', o: ['é automaticamente cancelado, sem exceção.', 'pode ser reaberto em 2027 nos limites do saldo, incorporado ao orçamento de 2027, pois o ato de autorização foi promulgado nos últimos quatro meses do exercício.', 'vira receita de 2027.', 'transforma-se em crédito suplementar.'], a: 1, e: 'CF art. 167, §2º: créditos especiais e extraordinários autorizados nos últimos quatro meses podem ser reabertos no exercício seguinte.' },
    { t: 'cpub', q: 'Assinale a alternativa INCORRETA sobre créditos adicionais:', o: ['Suplementares reforçam dotação existente.', 'Especiais atendem despesas sem dotação específica.', 'Extraordinários dependem de prévia autorização legislativa e indicação de recursos.', 'Suplementares e especiais são abertos por decreto do Executivo após autorização em lei.'], a: 2, e: 'Os extraordinários dispensam autorização prévia e indicação de fonte (art. 44 da Lei 4.320; CF art. 167, §3º).' },

    // ================= BALANÇOS E DVP =================
    { t: 'cpub', q: 'No Balanço Orçamentário, a diferença entre a receita realizada e a despesa empenhada é denominada:', o: ['superávit financeiro.', 'resultado orçamentário (superávit ou déficit de execução orçamentária).', 'resultado patrimonial.', 'resultado primário.'], a: 1, e: 'Resultado orçamentário = receita arrecadada − despesa empenhada. Não confundir com superávit financeiro (AF − PF) nem resultado patrimonial (VPA − VPD).' },
    { t: 'cpub', q: 'Um município previu receita de R$ 100 milhões e arrecadou R$ 108 milhões; fixou despesa de R$ 100 milhões e empenhou R$ 103 milhões. O resultado orçamentário foi:', o: ['déficit de R$ 3 milhões.', 'superávit de R$ 5 milhões.', 'superávit de R$ 8 milhões.', 'equilíbrio.'], a: 1, e: 'Realizada 108 − empenhada 103 = superávit de 5. O excesso de arrecadação (8) e a despesa acima do fixado (créditos adicionais) são informações distintas.' },
    { t: 'cpub', q: 'O Balanço Financeiro apresenta:', o: ['somente receitas e despesas orçamentárias.', 'receitas e despesas orçamentárias e extraorçamentárias, com os saldos em espécie do exercício anterior e para o seguinte.', 'bens, direitos e obrigações.', 'as variações aumentativas e diminutivas.'], a: 1, e: 'É um fluxo de caixa: saldo inicial + ingressos (orçamentários e extra) − dispêndios = saldo final.' },
    { t: 'cpub', q: 'No Balanço Financeiro, o saldo em espécie que passa para o exercício seguinte é obtido por:', o: ['receita prevista − despesa fixada.', 'saldo do exercício anterior + receitas (orçamentárias e extra) − despesas (orçamentárias e extra).', 'ativo − passivo.', 'VPA − VPD.'], a: 1, e: 'Estrutura do art. 103 da Lei 4.320.' },
    { t: 'cpub', q: 'A Demonstração das Variações Patrimoniais (DVP) assemelha-se, na contabilidade empresarial, à:', o: ['Demonstração dos Fluxos de Caixa.', 'Demonstração do Resultado do Exercício.', 'Demonstração das Mutações do PL.', 'Balanço Patrimonial.'], a: 1, e: 'A DVP confronta variações aumentativas e diminutivas e apura o resultado patrimonial, como a DRE apura o lucro.' },
    { t: 'cpub', q: 'São exemplos de variações patrimoniais aumentativas (VPA):', o: ['depreciação e provisões.', 'receita tributária reconhecida, receita de contribuições e ganhos com alienação de bens.', 'pagamento de fornecedores.', 'inscrição de restos a pagar.'], a: 1, e: 'VPA aumentam o PL: impostos, contribuições, exploração de bens, transferências recebidas, valorizações. Depreciação e provisões são VPD.' },
    { t: 'cpub', q: 'A depreciação de bens públicos e a constituição de provisões são registradas na DVP como:', o: ['variações patrimoniais aumentativas.', 'variações patrimoniais diminutivas.', 'receita extraorçamentária.', 'créditos adicionais.'], a: 1, e: 'Reduzem o patrimônio líquido sem execução orçamentária: VPD independentes da execução orçamentária.' },
    { t: 'cpub', q: 'No Balanço Patrimonial do setor público (MCASP), o patrimônio líquido corresponde a:', o: ['ativo financeiro − passivo financeiro.', 'ativo total − passivo total (obrigações).', 'receita − despesa.', 'ativo permanente − passivo permanente.'], a: 1, e: 'PL = Ativo − Passivo. O BP do MCASP apresenta também, em quadro anexo, os ativos e passivos financeiros/permanentes e o superávit financeiro por fonte.' },
    { t: 'cpub', q: 'Além dos quatro balanços da Lei 4.320/64, o MCASP exige a elaboração da:', o: ['Demonstração dos Fluxos de Caixa (DFC) e das Mutações do PL (DMPL, para empresas estatais dependentes), além das notas explicativas.', 'Demonstração do Valor Adicionado apenas.', 'Demonstração de Lucros Acumulados.', 'nenhuma outra demonstração.'], a: 0, e: 'As DCASP são: BO, BF, BP, DVP, DFC, DMPL (quando aplicável) e Notas Explicativas.' },

    // ================= CONTROLE NA ADMINISTRAÇÃO PÚBLICA =================
    { t: 'cpub', q: 'Segundo a Constituição (art. 70), a fiscalização contábil, financeira, orçamentária, operacional e patrimonial é exercida quanto aos aspectos de:', o: ['legalidade, legitimidade e economicidade, aplicação das subvenções e renúncia de receitas.', 'apenas legalidade.', 'conveniência e oportunidade política.', 'apenas eficiência.'], a: 0, e: 'Art. 70, caput, da CF.' },
    { t: 'cpub', q: 'Pela Constituição (art. 74), o sistema de controle interno deve ser mantido:', o: ['apenas pelo Poder Executivo.', 'de forma integrada pelos Poderes Legislativo, Executivo e Judiciário.', 'pelo Tribunal de Contas.', 'pelo Ministério Público.'], a: 1, e: 'Controle interno integrado entre os Poderes, com a finalidade, entre outras, de apoiar o controle externo.' },
    { t: 'cpub', q: 'Os responsáveis pelo controle interno, ao tomarem conhecimento de irregularidade, devem:', o: ['arquivar o caso.', 'dar ciência ao Tribunal de Contas, sob pena de responsabilidade solidária.', 'comunicar apenas ao Prefeito.', 'aguardar a próxima auditoria.'], a: 1, e: 'CF art. 74, §1º.' },
    { t: 'cpub', q: 'No município, o controle externo é exercido:', o: ['pelo Tribunal de Contas da União.', 'pela Câmara Municipal, com o auxílio do Tribunal de Contas do Estado (ou do Município, onde houver).', 'pela Controladoria-Geral da União.', 'pelo Ministério Público Estadual.'], a: 1, e: 'CF art. 31. É vedada a criação de novos tribunais de contas municipais (art. 31, §4º).' },
    { t: 'cpub', q: 'A Controladoria (órgão central de controle interno) tem como funções típicas:', o: ['executar as despesas e arrecadar tributos.', 'auditoria interna, controladoria/avaliação da gestão, ouvidoria e correição, além de orientar os gestores e apoiar o controle externo.', 'legislar sobre orçamento.', 'julgar as contas do Prefeito.'], a: 1, e: 'O controle interno orienta, avalia e fiscaliza a gestão; o julgamento das contas do Prefeito cabe à Câmara, com parecer do TC.' },
    { t: 'cpub', q: 'Na evolução do controle no Brasil, a Lei 4.320/64 introduziu o conceito de controle:', o: ['prévio, concomitante e subsequente (posterior), exercido pelo Executivo (interno) e pelo Legislativo (externo).', 'exclusivamente posterior.', 'apenas judicial.', 'somente pelo Tribunal de Contas.'], a: 0, e: 'Art. 77 da Lei 4.320: a verificação da legalidade dos atos de execução orçamentária será prévia, concomitante e subsequente.' },
    { t: 'cpub', q: 'O Decreto-Lei 200/1967 contribuiu para o controle na administração pública ao:', o: ['extinguir o controle interno.', 'estabelecer princípios de planejamento, coordenação, descentralização, delegação de competência e controle, racionalizando o controle interno.', 'criar os tribunais de contas municipais.', 'proibir auditorias.'], a: 1, e: 'O DL 200/67 é marco da reforma administrativa e trata o controle como princípio fundamental, voltado a resultados e à redução de formalismos.' },
    { t: 'cpub', q: 'Sobre o controle interno integrado, é correto afirmar que:', o: ['cada órgão controla apenas a si mesmo, sem padronização.', 'as unidades de controle interno dos diversos órgãos e Poderes atuam de forma coordenada, sob orientação de um órgão central (controladoria), com métodos e informações compartilhados.', 'substitui o controle externo.', 'é exercido somente pela Câmara Municipal.'], a: 1, e: 'Integração: sistema único, coordenado e padronizado entre os órgãos e Poderes.' },
    { t: 'cpub', q: 'As contas anuais do Prefeito são julgadas:', o: ['pelo Tribunal de Contas, em decisão definitiva.', 'pela Câmara Municipal, mediante parecer prévio do Tribunal de Contas, que só deixa de prevalecer por decisão de 2/3 dos vereadores.', 'pelo Poder Judiciário.', 'pela própria Controladoria do município.'], a: 1, e: 'CF art. 31, §§1º e 2º. Já as contas dos demais administradores (ordenadores) são julgadas pelo próprio Tribunal de Contas.' },
    { t: 'cpub', q: 'As contas do município ficam, durante sessenta dias, anualmente, à disposição de qualquer contribuinte para exame e apreciação, que poderá questionar-lhes a legitimidade. Essa é uma forma de controle:', o: ['interno.', 'social (popular).', 'judicial.', 'hierárquico.'], a: 1, e: 'CF art. 31, §3º: controle social. A LRF (arts. 48 e 49) também prevê transparência e acesso às contas.' },

    // ================= LRF =================
    { t: 'lrf', q: 'A LRF (LC 101/2000) tem como pressuposto da responsabilidade na gestão fiscal:', o: ['a ação planejada e transparente, com prevenção de riscos e correção de desvios que afetem o equilíbrio das contas públicas.', 'o aumento contínuo da arrecadação.', 'a centralização dos recursos na União.', 'a extinção dos tribunais de contas.'], a: 0, e: 'Art. 1º, §1º da LRF.' },
    { t: 'lrf', q: 'Para os municípios, a LRF fixa o limite da dívida consolidada? Assinale a alternativa correta:', o: ['A LRF fixa diretamente 60% da RCL.', 'A LRF remete a fixação dos limites globais da dívida consolidada a Resolução do Senado Federal, por proposta do Presidente da República.', 'Não há limite para a dívida municipal.', 'O limite é fixado pela Câmara Municipal.'], a: 1, e: 'Art. 30 da LRF; a Resolução do Senado 40/2001 fixou 1,2 vezes a RCL para os municípios.' },
    { t: 'lrf', q: 'O Anexo de Metas Fiscais da LDO deve conter metas anuais, para o exercício a que se refere e para os dois seguintes, relativas a:', o: ['receitas, despesas, resultados nominal e primário e montante da dívida pública.', 'número de servidores.', 'obras a serem licitadas.', 'índice de inflação.'], a: 0, e: 'Art. 4º, §1º da LRF.' },
    { t: 'lrf', q: 'Pela LRF, a criação ou aumento de despesa obrigatória de caráter continuado exige:', o: ['apenas publicação no diário oficial.', 'estimativa de impacto no exercício e nos dois seguintes e demonstração da origem dos recursos, com compensação por aumento permanente de receita ou redução permanente de despesa.', 'autorização do Tribunal de Contas.', 'referendo popular.'], a: 1, e: 'Art. 17 da LRF.' },
    { t: 'lrf', q: 'Segundo a LRF, são consideradas despesas de pessoal, entre outras:', o: ['apenas vencimentos de servidores ativos.', 'vencimentos e vantagens de ativos, inativos e pensionistas, encargos sociais, contribuições a entidades de previdência e contratos de terceirização que substituem servidores.', 'investimentos em obras.', 'juros da dívida.'], a: 1, e: 'Art. 18 da LRF. Indenizações por demissão e incentivos à demissão voluntária, entre outros, não são computados (art. 19, §1º).' },
    { t: 'lrf', q: 'Ultrapassado 95% do limite de despesa com pessoal (limite prudencial), fica vedado ao Poder:', o: ['pagar a folha de salários.', 'conceder vantagem ou aumento, criar cargo ou função, alterar estrutura de carreira, prover cargos (salvo reposição em educação, saúde e segurança) e pagar horas extras (salvo situações previstas na LDO).', 'realizar qualquer licitação.', 'publicar o RGF.'], a: 1, e: 'Art. 22, parágrafo único da LRF.' },
    { t: 'lrf', q: 'Se a despesa com pessoal ultrapassar o limite legal, a LRF determina que o ente, entre outras medidas:', o: ['aumente os tributos.', 'elimine o excedente nos dois quadrimestres seguintes (pelo menos um terço no primeiro), podendo reduzir cargos em comissão e funções de confiança e exonerar servidores não estáveis, conforme a CF.', 'suspenda a arrecadação.', 'peça intervenção federal.'], a: 1, e: 'Art. 23 da LRF c/c CF art. 169, §§3º e 4º.' },
    { t: 'lrf', q: 'Enquanto perdurar o excesso de despesa com pessoal não eliminado no prazo, o ente NÃO poderá:', o: ['pagar aposentadorias.', 'receber transferências voluntárias, obter garantia de outro ente e contratar operações de crédito (salvo refinanciamento da dívida e redução de despesa com pessoal).', 'publicar o RREO.', 'cobrar dívida ativa.'], a: 1, e: 'Art. 23, §3º da LRF.' },
    { t: 'lrf', q: 'A LRF veda ao titular de Poder ou órgão, nos últimos dois quadrimestres do mandato:', o: ['publicar relatórios.', 'contrair obrigação de despesa que não possa ser cumprida integralmente dentro do mandato ou que tenha parcelas a pagar no exercício seguinte sem suficiente disponibilidade de caixa.', 'conceder férias a servidores.', 'realizar licitações.'], a: 1, e: 'Art. 42 da LRF: regra dos restos a pagar no fim de mandato.' },
    { t: 'lrf', q: 'O Relatório de Gestão Fiscal (RGF) deve conter, entre outros:', o: ['a relação de contribuintes inadimplentes.', 'comparativo com os limites da LRF: despesa com pessoal, dívida consolidada, garantias, operações de crédito; e, no último quadrimestre, disponibilidade de caixa e restos a pagar.', 'o currículo dos gestores.', 'a lista de obras planejadas.'], a: 1, e: 'Art. 55 da LRF.' },
    { t: 'lrf', q: 'O RREO (Relatório Resumido da Execução Orçamentária) é de responsabilidade:', o: ['do Tribunal de Contas.', 'do Poder Executivo, abrangendo todos os Poderes e o Ministério Público, publicado até 30 dias após o fim de cada bimestre.', 'da Câmara Municipal.', 'do RPPS.'], a: 1, e: 'Art. 52 da LRF. O RGF, por sua vez, é emitido por cada titular de Poder/órgão.' },
    { t: 'lrf', q: 'A LRF determina que os recursos do RPPS sejam:', o: ['usados livremente pelo Tesouro municipal.', 'aplicados conforme as condições de mercado e observadas as normas do Conselho Monetário Nacional, vedada a aplicação em títulos da dívida do próprio ente e em empréstimos aos segurados ou ao Poder Público.', 'depositados em caixa único com os demais recursos municipais.', 'investidos apenas em imóveis.'], a: 1, e: 'Art. 43 da LRF, c/c Lei 9.717 e Resolução CMN 4.963/2021.' },
    { t: 'lrf', q: 'Transferência voluntária, segundo a LRF, é:', o: ['a entrega de recursos a outro ente a título de cooperação, auxílio ou assistência financeira, que não decorra de determinação constitucional, legal ou destinada ao SUS.', 'o repasse do FPM.', 'a cota-parte do ICMS.', 'o pagamento de precatórios.'], a: 0, e: 'Art. 25 da LRF. FPM e ICMS são transferências constitucionais (obrigatórias).' },
    { t: 'lrf', q: 'A "regra de ouro" das finanças públicas (CF art. 167, III, reforçada pela LRF art. 12, §2º) veda:', o: ['a realização de operações de crédito que excedam o montante das despesas de capital.', 'a vinculação de impostos.', 'o aumento de despesa com pessoal.', 'a concessão de isenções.'], a: 0, e: 'Não se pode tomar empréstimo para pagar despesa corrente, salvo autorização por maioria absoluta do Legislativo para créditos suplementares/especiais.' },
    { t: 'lrf', q: 'Operação de crédito, segundo a LRF, inclui:', o: ['apenas empréstimos bancários.', 'mútuo, abertura de crédito, emissão e aceite de título, aquisição financiada de bens, recebimento antecipado de venda a termo, arrendamento mercantil e outras operações assemelhadas, inclusive com derivativos.', 'somente emissão de títulos públicos.', 'as transferências constitucionais.'], a: 1, e: 'Art. 29, III da LRF. Questão de prova do Instituto Mais (IPMO 2025) cobrou essa definição literal.', src: 'Instituto Mais · IPMO 2025 (adaptada)' },

    // ================= RPPS: Lei 9.717/98 e CF art. 40; LC 241/2019 =================
    { t: 'rpps', q: 'A Lei 9.717/98 estabelece que os RPPS devem ser organizados com base em normas gerais de contabilidade e atuária, de modo a garantir:', o: ['o lucro do instituto.', 'o equilíbrio financeiro e atuarial.', 'a isenção de contribuições.', 'a autonomia do Legislativo.'], a: 1, e: 'Art. 1º, caput, da Lei 9.717/98 e CF art. 40, caput.' },
    { t: 'rpps', q: 'Entre as regras da Lei 9.717/98, consta a exigência de:', o: ['avaliação atuarial inicial e em cada balanço, para organização e revisão do plano de custeio e benefícios.', 'avaliação atuarial apenas a cada dez anos.', 'dispensa de contabilidade própria.', 'aplicação dos recursos exclusivamente em imóveis.'], a: 0, e: 'Art. 1º, I. Questão do Instituto Mais (IPMO 2025) cobrou exatamente as lacunas "inicial / balanço / custeio e benefícios".', src: 'Instituto Mais · IPMO 2025 (adaptada)' },
    { t: 'rpps', q: 'A Lei 9.717/98 exige, quanto às informações do RPPS:', o: ['sigilo total sobre as contas.', 'pleno acesso dos segurados às informações relativas à gestão do regime e registro contábil individualizado das contribuições de cada servidor e do ente.', 'divulgação apenas ao Tribunal de Contas.', 'publicação somente no fim do mandato.'], a: 1, e: 'Art. 1º, VI e VII da Lei 9.717/98 (transparência e registro individualizado).' },
    { t: 'rpps', q: 'A contribuição do ente ao RPPS (CF art. 40 e Lei 9.717, art. 2º) deve ser:', o: ['no mínimo igual à do servidor ativo e no máximo o dobro dela, com o produto da arrecadação contabilizado em conta específica.', 'livre.', 'igual a 11% sempre.', 'facultativa.'], a: 0, e: 'Questão do Instituto Mais (IPMO 2025) com lacunas: Constituição Federal / o dobro / específica.', src: 'Instituto Mais · IPMO 2025 (adaptada)' },
    { t: 'rpps', q: 'Os entes podem adotar, para apuração dos compromissos e custos do plano de benefícios do RPPS, os regimes financeiros de:', o: ['capitalização, apenas.', 'repartição simples, apenas.', 'capitalização, repartição de capitais de cobertura e repartição simples.', 'nenhum, pois o RPPS não tem plano de custeio.'], a: 2, e: 'Os três regimes financeiros são admitidos (Portaria MTP 1.467/2022). Questão do Instituto Mais (IPMO 2025).', src: 'Instituto Mais · IPMO 2025 (adaptada)' },
    { t: 'rpps', q: 'A alíquota de contribuição dos servidores ativos ao RPPS, após a EC 103/2019:', o: ['pode ser inferior à do RGPS.', 'não pode ser inferior à dos servidores da União (14%), salvo se o RPPS não tiver déficit atuarial, caso em que a alíquota não pode ser inferior à do RGPS.', 'é sempre 11%.', 'é definida livremente pelo instituto.'], a: 1, e: 'EC 103/2019, art. 9º, §4º. A alíquota é fixada em lei do ente.' },
    { t: 'rpps', q: 'Segundo a CF (art. 40, §22), lei complementar federal estabelecerá normas gerais de organização, funcionamento e responsabilidade na gestão dos RPPS, dispondo, entre outros, sobre:', o: ['requisitos para sua extinção e migração para o RGPS, modelo de arrecadação, fiscalização, certificação dos dirigentes e condições para instituição de fundos.', 'apenas o salário dos dirigentes.', 'a lista de aposentados.', 'a cor dos prédios.'], a: 0, e: 'Enquanto não editada a nova lei complementar, aplica-se a Lei 9.717/98.' },
    { t: 'rpps', q: 'O RPPS pode ter mais de uma unidade gestora?', o: ['Sim, uma por Poder.', 'Não. É vedada a existência de mais de um RPPS e de mais de uma unidade gestora por ente, ressalvado o regime dos militares (CF art. 40, §20).', 'Sim, se autorizado pelo Tribunal de Contas.', 'Sim, uma para ativos e outra para inativos.'], a: 1, e: 'Unidade gestora única: no caso de São Sebastião, o SSPREV.' },
    { t: 'rpps', q: 'Os afastamentos por incapacidade temporária para o trabalho e o salário-maternidade dos servidores vinculados ao RPPS são, após a EC 103/2019:', o: ['pagos pelo RPPS como benefícios previdenciários.', 'pagos diretamente pelo ente (Tesouro), não sendo mais benefícios do RPPS.', 'pagos pelo INSS.', 'pagos pelo sindicato.'], a: 1, e: 'EC 103/2019, art. 9º, §§2º e 3º: o RPPS cobre apenas aposentadorias e pensão por morte.' },
    { t: 'rpps', q: 'O Certificado de Regularidade Previdenciária (CRP), emitido pelo Ministério da Previdência:', o: ['é exigido para o ente receber transferências voluntárias, celebrar convênios e contratar empréstimos com instituições federais.', 'não tem efeito prático.', 'é emitido pela Câmara Municipal.', 'substitui a avaliação atuarial.'], a: 0, e: 'Lei 9.717, art. 7º: o descumprimento das normas impede transferências voluntárias, empréstimos e repasse de compensação previdenciária.' },
    { t: 'rpps', q: 'A Lei Complementar Municipal nº 241/2019 de São Sebastião dispõe sobre:', o: ['a criação da Autarquia Previdenciária (SSPREV) e a reestruturação do Fundo de Aposentadoria e Pensões dos Servidores de São Sebastião (FAPS).', 'o Estatuto dos Servidores.', 'a Lei Orgânica do Município.', 'o plano de carreira dos professores.'], a: 0, e: 'É a lei de criação do SSPREV, conforme o conteúdo programático do edital. Leia a lei seca: natureza, estrutura, órgãos e receitas.' },
    { t: 'rpps', q: 'Sendo o SSPREV uma autarquia municipal, ele possui:', o: ['personalidade jurídica de direito privado e fins lucrativos.', 'personalidade jurídica de direito público, patrimônio e receitas próprios e autonomia administrativa e financeira, vinculado à Administração municipal.', 'natureza de empresa pública.', 'natureza de órgão da Câmara Municipal.'], a: 1, e: 'Autarquia: pessoa jurídica de direito público criada por lei para executar atividade típica do Estado (DL 200/67, art. 5º, I).' },
    { t: 'rpps', q: 'O FAPS, reestruturado pela LC 241/2019, tem a natureza de:', o: ['fundo de natureza contábil/financeira destinado ao custeio das aposentadorias e pensões dos servidores do município, gerido pela autarquia previdenciária.', 'fundo de investimento privado.', 'fundo eleitoral.', 'conta do Tesouro Nacional.'], a: 0, e: 'Fundos previdenciários dos RPPS acumulam as contribuições e seus rendimentos para pagar os benefícios (Lei 9.717, art. 6º).' },
    { t: 'rpps', q: 'Os conselhos típicos de um RPPS (como o SSPREV) são:', o: ['Conselho Deliberativo (ou de Administração) e Conselho Fiscal, com representação de servidores e do ente.', 'Conselho de Vereadores e Conselho Tutelar.', 'apenas um Conselho de Investimentos privado.', 'Conselho Monetário Nacional.'], a: 0, e: 'A Lei 9.717 (art. 1º, VI) e a Portaria 1.467/2022 exigem participação de representantes dos segurados nos colegiados e instâncias de decisão.' },
    { t: 'rpps', q: 'A gestão dos recursos do RPPS deve observar os limites de aplicação definidos pelo:', o: ['Conselho Monetário Nacional (Resolução CMN), em segmentos de renda fixa, renda variável, exterior, imóveis etc.', 'Tribunal de Contas do Estado.', 'Prefeito, por decreto.', 'Banco do Brasil.'], a: 0, e: 'Lei 9.717, art. 6º, IV e LRF art. 43. Atualmente, Resolução CMN 4.963/2021.' },

    // ================= LICITAÇÕES (Lei 14.133/2021) =================
    { t: 'lic', q: 'Segundo a Lei 14.133/2021, é hipótese de DISPENSA de licitação:', o: ['contratação de serviços técnicos especializados de natureza predominantemente intelectual com profissionais de notória especialização.', 'contratação de profissionais para compor a comissão de avaliação de critérios de técnica, quando se tratar de profissional técnico de notória especialização.', 'aquisição de bens que só possam ser fornecidos por representante comercial exclusivo.', 'contratação de artista consagrado pela crítica.'], a: 1, e: 'As demais são inexigibilidade (art. 74). Questão do Instituto Mais (IPMO 2025).', src: 'Instituto Mais · IPMO 2025 (adaptada)' },
    { t: 'lic', q: 'O procedimento auxiliar utilizado para selecionar previamente licitantes ou bens que atendam às exigências técnicas ou de qualidade estabelecidas pela Administração é denominado:', o: ['credenciamento.', 'registro cadastral.', 'pré-qualificação.', 'procedimento de manifestação de interesse.'], a: 2, e: 'Art. 80 da Lei 14.133. Questão do Instituto Mais (IPMO 2025).', src: 'Instituto Mais · IPMO 2025 (adaptada)' },
    { t: 'lic', q: 'Na contratação que gere receita e no contrato de eficiência que gere economia para a Administração, sem investimento, o prazo pode ser de até:', o: ['5 anos.', '10 anos.', '35 anos.', '2 anos.'], a: 1, e: 'Art. 110, I da Lei 14.133 (10 anos sem investimento; 35 anos com investimento). Questão do Instituto Mais (IPMO 2025).', src: 'Instituto Mais · IPMO 2025 (adaptada)' },
    { t: 'lic', q: 'São procedimentos auxiliares das licitações e contratações, segundo o art. 78 da Lei 14.133/2021:', o: ['pregão, concorrência e leilão.', 'credenciamento, pré-qualificação, procedimento de manifestação de interesse, sistema de registro de preços e registro cadastral.', 'tomada de preços e convite.', 'adjudicação e homologação.'], a: 1, e: 'Procedimentos auxiliares não são modalidades: apoiam as contratações.' },
    { t: 'lic', q: 'O Sistema de Registro de Preços (SRP):', o: ['é uma modalidade de licitação.', 'é procedimento auxiliar em que preços são registrados em ata para contratações futuras, sem obrigar a Administração a contratar.', 'obriga a Administração a comprar todo o quantitativo registrado.', 'só pode ser usado pela União.'], a: 1, e: 'Art. 82 e seguintes. A ata de registro de preços tem validade de 1 ano, prorrogável por igual período.' },
    { t: 'lic', q: 'Na Lei 14.133/2021, a fase preparatória da licitação inclui, entre outros documentos:', o: ['o estudo técnico preliminar, o termo de referência ou projeto básico, a pesquisa de preços e a análise de riscos.', 'apenas o edital.', 'o balanço patrimonial do município.', 'a ata de julgamento.'], a: 0, e: 'Art. 18 da Lei 14.133: planejamento da contratação.' },
    { t: 'lic', q: 'O critério de julgamento "maior desconto":', o: ['aplica-se ao leilão.', 'tem como referência o preço global fixado no edital, estendendo-se o desconto aos eventuais aditivos.', 'só é usado no diálogo competitivo.', 'equivale à melhor técnica.'], a: 1, e: 'Art. 34, §2º da Lei 14.133.' },
    { t: 'lic', q: 'Em regra, na Lei 14.133/2021, a fase de habilitação ocorre:', o: ['antes da apresentação das propostas.', 'após o julgamento das propostas, podendo ser antecipada mediante ato motivado com justificativa no edital.', 'simultaneamente ao pagamento.', 'após a assinatura do contrato.'], a: 1, e: 'Art. 17, §1º: inversão de fases permitida por ato motivado.' },
    { t: 'lic', q: 'A modalidade CONCORRÊNCIA destina-se à contratação de:', o: ['bens e serviços comuns, apenas.', 'bens e serviços especiais e obras e serviços comuns e especiais de engenharia.', 'alienação de bens.', 'trabalhos artísticos.'], a: 1, e: 'Art. 6º, XXXVIII. Para bens e serviços comuns, o pregão é obrigatório; obras e serviços de engenharia vão por concorrência (ou pregão, se serviço comum de engenharia).' },
    { t: 'lic', q: 'A Lei 14.133/2021 exige, para licitar, a divulgação do edital:', o: ['apenas no quadro de avisos da prefeitura.', 'no Portal Nacional de Contratações Públicas (PNCP), facultada a divulgação adicional no sítio eletrônico oficial do ente.', 'somente em jornal de grande circulação.', 'exclusivamente no Diário Oficial da União.'], a: 1, e: 'Art. 54 da Lei 14.133.' },
    { t: 'lic', q: 'Quanto à duração, os contratos administrativos da Lei 14.133/2021:', o: ['têm prazo máximo de 12 meses em qualquer caso.', 'têm o prazo definido no edital, observadas as regras da lei: serviços e fornecimentos contínuos até 5 anos (prorrogáveis até 10), contratos com investimento até 35 anos etc.', 'são sempre por prazo indeterminado.', 'não podem ser prorrogados.'], a: 1, e: 'Arts. 105 a 114 da Lei 14.133.' },
    { t: 'lic', q: 'A alteração unilateral dos contratos pela Administração (acréscimos ou supressões) é limitada, em regra, a:', o: ['10% do valor inicial.', '25% do valor inicial atualizado (50% para reforma de edifício ou equipamento, no caso de acréscimos).', '100%.', 'não há limite.'], a: 1, e: 'Art. 125 da Lei 14.133.' },
    { t: 'lic', q: 'Pela Lei 14.133/2021, o pagamento das obrigações contratuais deve observar:', o: ['a preferência do gestor.', 'a ordem cronológica para cada fonte diferenciada de recursos, por categoria de contrato, salvo exceções justificadas.', 'o valor do contrato, pagando primeiro os maiores.', 'a data da licitação.'], a: 1, e: 'Art. 141 da Lei 14.133.' },
    { t: 'lic', q: 'A dispensa de licitação em razão do valor (art. 75, I e II) tem seus limites:', o: ['fixos para sempre.', 'atualizados anualmente pelo Poder Executivo federal, pelo IPCA, com valores distintos para obras/serviços de engenharia e para compras/demais serviços.', 'definidos por cada município.', 'definidos pelo Tribunal de Contas.'], a: 1, e: 'Art. 182 da Lei 14.133. Em 2025, aproximadamente R$ 125 mil (engenharia) e R$ 62 mil (demais).' },
    { t: 'lic', q: 'A contratação direta por emergência ou calamidade pública (art. 75, VIII) está limitada a:', o: ['parcelas de obras e serviços que possam ser concluídas no prazo máximo de 1 ano, contado da data da ocorrência, vedadas a prorrogação e a recontratação.', 'qualquer prazo.', '5 anos.', '30 dias.'], a: 0, e: 'Art. 75, VIII da Lei 14.133.' },

    // ================= LÍNGUA PORTUGUESA =================
    { t: 'port', texto: 'A previdência dos servidores municipais vive um dilema conhecido: cada vez menos ativos contribuem para um número crescente de aposentados. Sem medidas de equilíbrio, o fundo que paga os benefícios tende a se esgotar, e quem perde, no fim, é o próprio servidor.', q: 'De acordo com o texto, o "dilema" da previdência dos servidores decorre:', o: ['da má gestão dos recursos pelos prefeitos.', 'da relação desproporcional entre contribuintes ativos e beneficiários aposentados.', 'da falta de interesse dos servidores em se aposentar.', 'do excesso de medidas de equilíbrio adotadas.'], a: 1, e: 'O texto afirma que "cada vez menos ativos contribuem para um número crescente de aposentados". As demais alternativas extrapolam ou contradizem o texto.' },
    { t: 'port', texto: 'A previdência dos servidores municipais vive um dilema conhecido: cada vez menos ativos contribuem para um número crescente de aposentados. Sem medidas de equilíbrio, o fundo que paga os benefícios tende a se esgotar, e quem perde, no fim, é o próprio servidor.', q: 'Pode-se concluir do texto que:', o: ['o autor é contra a aposentadoria dos servidores.', 'o autor defende, implicitamente, a adoção de medidas que equilibrem o fundo previdenciário.', 'o fundo já se esgotou.', 'os aposentados são os responsáveis pelo problema.'], a: 1, e: 'Inferência: ao dizer "sem medidas de equilíbrio, o fundo tende a se esgotar", o autor sugere que tais medidas são necessárias. "Tende a" indica tendência, não fato consumado.' },
    { t: 'port', texto: 'Estudar para concurso é como preparar uma maratona: não adianta correr quarenta quilômetros na véspera. O corpo e a mente respondem à constância, não ao exagero de última hora.', q: 'No texto, a comparação com a maratona serve para destacar que:', o: ['o estudo deve ser concentrado nos últimos dias.', 'a preparação exige regularidade ao longo do tempo.', 'concurso é uma atividade física.', 'o exagero de última hora é recomendável.'], a: 1, e: 'A frase central é "respondem à constância, não ao exagero de última hora".' },
    { t: 'port', q: 'Em "O servidor tomou posse e, dias depois, entrou em exercício", a palavra "posse" é empregada em sentido:', o: ['figurado, significando domínio sobre bens.', 'próprio (denotativo), referindo-se ao ato formal de investidura no cargo.', 'conotativo, indicando orgulho.', 'figurado, significando aposentadoria.'], a: 1, e: 'Sentido próprio é o literal, dicionarizado para o contexto: posse = investidura no cargo público.' },
    { t: 'port', q: 'Assinale a alternativa em que a palavra destacada está em sentido FIGURADO:', o: ['A balança pesou dois quilos de arroz.', 'O orçamento do município foi aprovado ontem.', 'A notícia caiu como uma bomba na repartição.', 'O prédio da prefeitura tem três andares.'], a: 2, e: '"Caiu como uma bomba" é figurado (metáfora/comparação): a notícia causou grande impacto.' },
    { t: 'port', q: 'O sinônimo mais adequado para "vedado", em "é vedado o empenho sem dotação", é:', o: ['permitido.', 'proibido.', 'recomendado.', 'obrigatório.'], a: 1, e: 'Vedado = proibido. Termo muito frequente nos textos legais.' },
    { t: 'port', q: 'O antônimo de "superávit" é:', o: ['equilíbrio.', 'déficit.', 'excesso.', 'arrecadação.'], a: 1, e: 'Superávit (sobra) × déficit (falta).' },
    { t: 'port', q: 'São palavras parônimas (parecidas na grafia, diferentes no sentido):', o: ['sessão / seção / cessão.', 'ratificar / retificar.', 'manga (fruta) / manga (da camisa).', 'rico / pobre.'], a: 1, e: 'Ratificar (confirmar) e retificar (corrigir) são parônimos. Sessão/seção/cessão são homônimos homófonos; manga/manga são homônimos perfeitos; rico/pobre, antônimos.' },
    { t: 'port', q: 'Assinale a alternativa em que TODAS as palavras estão grafadas corretamente:', o: ['excessão, previlégio, beneficiente.', 'exceção, privilégio, beneficente.', 'excessão, privilégio, beneficente.', 'exceção, previlégio, beneficiente.'], a: 1, e: 'Exceção, privilégio e beneficente são as formas corretas.' },
    { t: 'port', q: 'Complete: "O ___ dos servidores foi analisado; a ___ tomou a decisão com ___."', o: ['recurso / seção / discrição', 'recurso / sessão / discrição', 'recurso / seção / descrição', 'recurço / sessão / discreção'], a: 1, e: 'Sessão = reunião (a sessão da Câmara); seção = divisão/parte; discrição = reserva/prudência; descrição = ato de descrever.' },
    { t: 'port', q: 'Quanto à acentuação, assinale a alternativa correta:', o: ['Rubrica, ítem, gratuíto.', 'Rubrica, item, gratuito.', 'Rúbrica, item, gratuito.', 'Rubrica, item, gratúito.'], a: 1, e: 'Rubrica é paroxítona (ru-BRI-ca), sem acento; item e gratuito também não levam acento (gratuito tem ditongo "ui" átono, pronuncia-se gra-TUI-to).' },
    { t: 'port', q: 'Assinale a alternativa cujas palavras são acentuadas pela MESMA regra:', o: ['pública, órgão, servidor.', 'contábil, útil, fácil.', 'café, público, você.', 'também, lâmpada, saúde.'], a: 1, e: 'Contábil, útil e fácil são paroxítonas terminadas em L. Público/lâmpada são proparoxítonas; café/você são oxítonas; saúde leva acento por hiato.' },
    { t: 'port', q: 'A palavra "saída" recebe acento porque:', o: ['é proparoxítona.', 'o "i" tônico forma hiato com a vogal anterior, sozinho na sílaba.', 'termina em "a".', 'é monossílabo tônico.'], a: 1, e: 'Regra do hiato: i/u tônicos, sozinhos na sílaba ou seguidos de s, separados da vogal anterior (sa-í-da, sa-ú-de, ba-ú).' },
    { t: 'port', q: 'Com o Novo Acordo Ortográfico, deixou de ser acentuada a palavra:', o: ['heroico.', 'herói.', 'papéis.', 'anéis.'], a: 0, e: 'Perderam o acento os ditongos abertos "ei"/"oi" em PAROXÍTONAS (heroico, ideia, jiboia). Oxítonas mantêm (herói, papéis, anéis).' },
    { t: 'port', q: 'Assinale a frase em que a vírgula foi empregada corretamente:', o: ['O servidor, entregou o relatório ao chefe.', 'Entregou, o servidor o relatório ao chefe.', 'Na manhã de ontem, o servidor entregou o relatório ao chefe.', 'O servidor entregou, o relatório ao chefe.'], a: 2, e: 'Vírgula após adjunto adverbial deslocado para o início está correta. Nunca separar sujeito do verbo ou verbo do objeto.' },
    { t: 'port', q: 'Em "Prefeito, a Câmara aprovou o orçamento", a vírgula isola um:', o: ['aposto.', 'vocativo.', 'adjunto adverbial.', 'sujeito.'], a: 1, e: 'Vocativo: chamamento ao interlocutor, sempre isolado por vírgula.' },
    { t: 'port', q: 'Em "O SSPREV, autarquia previdenciária do município, foi criado em 2019", a expressão entre vírgulas é um:', o: ['vocativo.', 'aposto explicativo.', 'sujeito composto.', 'predicativo.'], a: 1, e: 'Aposto explicativo: explica o termo anterior e vem entre vírgulas.' },
    { t: 'port', q: 'O uso do ponto e vírgula é adequado em:', o: ['para separar sujeito e predicado.', 'para separar itens de uma enumeração longa ou orações coordenadas extensas que já contêm vírgulas, como nos incisos de leis.', 'no final de frases interrogativas.', 'antes de qualquer conjunção.'], a: 1, e: 'É o uso típico em textos legais: "I - ...; II - ...; III - ...".' },
    { t: 'port', q: 'Os dois-pontos são usados para:', o: ['introduzir uma enumeração, uma citação ou um esclarecimento.', 'separar sujeito de verbo.', 'indicar pausa final.', 'substituir a vírgula do vocativo.'], a: 0, e: 'Ex.: "São três os créditos adicionais: suplementares, especiais e extraordinários."' },
    { t: 'port', q: 'Em "Aqueles servidores estudaram muito para a prova", as palavras "aqueles", "muito" e "para" são, respectivamente:', o: ['pronome demonstrativo, advérbio de intensidade, preposição.', 'artigo, adjetivo, conjunção.', 'pronome possessivo, substantivo, advérbio.', 'numeral, advérbio, pronome.'], a: 0, e: '"Aqueles" determina o substantivo (pronome demonstrativo); "muito" modifica o verbo (advérbio); "para" liga termos (preposição).' },
    { t: 'port', q: 'Em "Os dois primeiros candidatos foram aprovados", as palavras "dois" e "primeiros" são:', o: ['adjetivos.', 'numerais cardinal e ordinal, respectivamente.', 'pronomes indefinidos.', 'advérbios.'], a: 1, e: 'Dois = numeral cardinal (quantidade); primeiros = numeral ordinal (ordem).' },
    { t: 'port', q: 'Em "A contadora conferiu cuidadosamente o balanço", a palavra "cuidadosamente" é:', o: ['adjetivo, pois qualifica a contadora.', 'advérbio de modo, pois modifica o verbo "conferiu".', 'substantivo abstrato.', 'conjunção.'], a: 1, e: 'Advérbios terminados em -mente indicam modo e modificam o verbo.' },
    { t: 'port', q: 'Assinale a alternativa em que a palavra "que" é conjunção integrante:', o: ['O relatório que você enviou está correto.', 'Espero que o resultado saia logo.', 'Que prova difícil!', 'Trabalhou tanto que adoeceu.'], a: 1, e: 'Em "espero que...", o "que" introduz oração substantiva objetiva direta (completa o verbo esperar): conjunção integrante. Na A é pronome relativo; na C, pronome/advérbio intensificador; na D, conjunção consecutiva.' },
    { t: 'port', q: 'Em "Estude com constância, POIS a prova está próxima", a conjunção destacada estabelece relação de:', o: ['oposição.', 'explicação.', 'alternância.', 'tempo.'], a: 1, e: '"Pois" depois do verbo, iniciando a segunda oração, é conjunção coordenativa explicativa (justifica a ordem dada).' },
    { t: 'port', q: 'Em "Caso o candidato chegue atrasado, não poderá fazer a prova", a oração destacada expressa:', o: ['causa.', 'condição.', 'concessão.', 'finalidade.'], a: 1, e: '"Caso", "se", "desde que", "contanto que" são conjunções condicionais.' },
    { t: 'port', q: 'Em "Estudou para que fosse aprovada", a locução "para que" indica:', o: ['finalidade.', 'causa.', 'tempo.', 'comparação.'], a: 0, e: 'Finais: para que, a fim de que.' },
    { t: 'port', q: 'Em "Ou você estuda com método, ou perde tempo", a relação entre as orações é de:', o: ['adição.', 'alternância.', 'conclusão.', 'explicação.'], a: 1, e: 'Conjunções alternativas: ou...ou, ora...ora, quer...quer.' },
    { t: 'port', q: 'Assinale a frase CORRETA quanto à concordância verbal:', o: ['Fazem três anos que ele trabalha na prefeitura.', 'Houveram muitos recursos contra o gabarito.', 'A maioria dos candidatos chegou cedo.', 'Chegou os candidatos atrasados.'], a: 2, e: '"A maioria dos candidatos" admite o verbo no singular (concordando com o núcleo "maioria") ou no plural. "Faz três anos" e "Houve muitos recursos" (impessoais); "Chegaram os candidatos".' },
    { t: 'port', q: 'Assinale a alternativa correta quanto à concordância:', o: ['Vossa Excelência está enganado em suas afirmações.', 'Vossa Excelência estais enganada.', 'Vossa Excelência estão enganados.', 'Vossa Excelência estás enganado.'], a: 0, e: 'Pronomes de tratamento levam o verbo e os pronomes à 3ª pessoa; o adjetivo concorda com o sexo da pessoa (enganado/enganada).' },
    { t: 'port', q: 'Complete: "___ bastante problemas e ___ necessário resolvê-los."', o: ['Existe / é', 'Existem / é', 'Existem / são', 'Existe / são'], a: 1, e: '"Existir" é pessoal: concorda com "problemas" (existem). "É necessário" fica invariável sem artigo antes do sujeito.' },
    { t: 'port', q: 'Quanto à concordância nominal, está correta a frase:', o: ['Segue anexo as planilhas e os relatórios.', 'Seguem anexos as planilhas e os relatórios.', 'Seguem anexas os relatórios e as planilhas.', 'Segue anexa as planilhas.'], a: 1, e: 'Anexo concorda com os substantivos; com gênero misto, prevalece o masculino plural: "anexos".' },
    { t: 'port', q: 'Assinale a opção correta quanto à concordância nominal:', o: ['Ela mesmo resolveu as questões.', 'Elas mesmas resolveram as questões.', 'Elas próprio resolveram.', 'Ela mesmos resolveu.'], a: 1, e: '"Mesmo" e "próprio", quando reforçam o sujeito, concordam com ele em gênero e número.' },
    { t: 'port', q: 'Quanto à regência, assinale a alternativa correta:', o: ['O servidor chegou na repartição às 8h.', 'O servidor chegou à repartição às 8h.', 'O servidor chegou a repartição às 8h.', 'O servidor chegou em a repartição.'], a: 1, e: 'Chegar A algum lugar (norma culta), com crase diante de substantivo feminino determinado: "à repartição".' },
    { t: 'port', q: 'Assinale a frase correta quanto à regência verbal:', o: ['Prefiro mais estudar à noite do que de manhã.', 'Prefiro estudar à noite a estudar de manhã.', 'Prefiro estudar à noite do que de manhã.', 'Prefiro mais estudar à noite que de manhã.'], a: 1, e: 'Preferir X A Y, sem "mais" e sem "do que".' },
    { t: 'port', q: 'Quanto à regência, está correta:', o: ['O chefe lembrou do prazo e avisou os servidores.', 'O chefe lembrou-se do prazo e avisou os servidores.', 'O chefe se lembrou o prazo.', 'O chefe lembrou-se o prazo.'], a: 1, e: 'Lembrar algo (direto) OU lembrar-se DE algo (pronominal + preposição). Avisar alguém de algo.' },
    { t: 'port', q: 'Em "O documento ___ me referi está ___ disposição", as lacunas são preenchidas corretamente por:', o: ['que / a', 'a que / à', 'ao qual / a', 'de que / à'], a: 1, e: 'Referir-se A algo → "a que me referi"; "estar à disposição" (locução feminina com crase).' },
    { t: 'port', q: 'Assinale a alternativa em que o uso do acento grave (crase) está correto:', o: ['Vou à Osasco amanhã.', 'Entregou o ofício à diretoria às 10 horas.', 'Ele se referiu à alguém da equipe.', 'Estamos à disposição à partir de segunda.'], a: 1, e: 'Crase antes de substantivo feminino determinado (à diretoria) e em locuções de hora (às 10 horas). Não há crase antes de cidade sem artigo (a Osasco), de pronome indefinido (a alguém) ou de verbo (a partir).' },
    { t: 'port', q: 'Há crase obrigatória em:', o: ['Ela foi a pé até a prefeitura.', 'Refiro-me a ela.', 'Trabalhamos de segunda a sexta.', 'O relatório foi entregue à secretária.'], a: 3, e: 'Antes de palavra masculina (pé), pronome pessoal (ela) e em "de ... a ..." sem artigo não há crase. "À secretária": substantivo feminino determinado.' },
    { t: 'port', q: 'Assinale a alternativa correta quanto à colocação pronominal:', o: ['Não entregaram-me o documento.', 'Entregar-me-ão o documento amanhã.', 'Me entregaram o documento ontem.', 'Jamais entregar-lhe-ei o documento.'], a: 1, e: 'Futuro do presente sem palavra atrativa: mesóclise. Palavras negativas (não, jamais) exigem próclise; não se inicia frase com pronome oblíquo.' },
    { t: 'port', q: 'Está correta a colocação do pronome em:', o: ['Tudo se resolveu rapidamente.', 'Tudo resolveu-se rapidamente.', 'Se resolveu tudo rapidamente.', 'Tudo resolver-se-ia-se.'], a: 0, e: 'Pronome indefinido ("tudo") atrai o pronome oblíquo: próclise.' },
    { t: 'port', q: 'Em "Os candidatos que se prepararam bem foram aprovados", a próclise é justificada por:', o: ['verbo no futuro.', 'presença de pronome relativo ("que").', 'início de frase.', 'presença de vírgula.'], a: 1, e: 'Pronomes relativos (que, quem, cujo, onde) são palavras atrativas e exigem próclise.' },
    { t: 'port', q: 'Quanto ao emprego dos porquês, assinale a frase correta:', o: ['Ninguém sabe o porque da decisão.', 'Ela estudou porque queria passar.', 'Por que ela não veio? Porquê estava doente.', 'Não sei porque ele faltou.'], a: 1, e: '"Porque" = conjunção causal/explicativa. "O porquê" (substantivo, com acento e artigo); "por quê" no fim de frase; "por que" em perguntas e no sentido de "pelo qual" ("não sei por que ele faltou").' },

    // ================= LEGISLAÇÃO MUNICIPAL: Estatuto (LC 146/2011) e Lei Orgânica =================
    { t: 'leg', q: 'Segundo o art. 6º da LC 146/2011, os cargos de carreira e os cargos isolados são, respectivamente, de provimento:', o: ['sempre em comissão; efetivo.', 'sempre efetivo; efetivo ou em comissão, conforme a lei que os criar.', 'efetivo ou em comissão; sempre em comissão.', 'temporário; efetivo.'], a: 1, e: 'Art. 6º. Cargo isolado é o que não constitui carreira (art. 2º, IV). O Quadro de Pessoal tem parte permanente (carreira, concurso) e parte suplementar (comissão) (art. 7º).', src: 'LC 146/2011 (Estatuto)' },
    { t: 'leg', q: 'Cargo efetivo e cargo em comissão diferenciam-se porque:', o: ['o efetivo é provido por concurso público e confere estabilidade após o estágio probatório; o em comissão é de livre nomeação e exoneração, destinado às atribuições de direção, chefia e assessoramento.', 'o efetivo não exige concurso.', 'o em comissão exige concurso.', 'não há diferença de regime.'], a: 0, e: 'CF art. 37, II e V.' },
    { t: 'leg', q: 'A investidura em cargo público ocorre com:', o: ['a nomeação.', 'a posse.', 'o exercício.', 'a aprovação no concurso.'], a: 1, e: 'Nomeação é o ato de provimento; a investidura se dá com a posse (assinatura do termo); o exercício é o efetivo desempenho das atribuições.' },
    { t: 'leg', q: 'Se a posse não ocorrer no prazo de 10 dias úteis contados da publicação do ato de provimento, segundo a LC 146/2011:', o: ['o prazo é prorrogado automaticamente.', 'o ato de provimento será tornado sem efeito.', 'o servidor é demitido.', 'o servidor toma posse quando quiser.'], a: 1, e: 'Art. 27, §4º. Exceções ao prazo: gestante a partir do 8º mês, serviço militar e licença saúde de quem já é servidor (caput).', src: 'LC 146/2011 (Estatuto)' },
    { t: 'leg', q: 'Pela LC 146/2011, o servidor em estágio probatório que for reprovado em uma das avaliações de desempenho:', o: ['é automaticamente exonerado, sem defesa.', 'será considerado inapto e desligado, se, após exercida sua ampla defesa, esta for considerada insatisfatória; a avaliação e a eventual exoneração devem concluir-se dentro dos 3 anos.', 'repete apenas a avaliação.', 'é transferido para outro cargo.'], a: 1, e: 'Art. 39, caput e §1º. São três avaliações, a cada 10 meses (art. 38).', src: 'LC 146/2011 (Estatuto)' },
    { t: 'leg', q: 'A readaptação do servidor ocorre quando:', o: ['ele é aprovado em novo concurso.', 'ele sofre limitação em sua capacidade física ou mental, verificada em inspeção médica, e é investido em cargo com atribuições compatíveis.', 'ele é demitido.', 'ele completa 20 anos de serviço.'], a: 1, e: 'Readaptação: forma de provimento por motivo de saúde, respeitada a habilitação e o nível de escolaridade.' },
    { t: 'leg', q: 'No Estatuto de São Sebastião (LC 146/2011), o deslocamento de servidor efetivo, com o respectivo cargo, para o quadro de outro órgão da Administração municipal, no mesmo Poder, chama-se:', o: ['remoção.', 'redistribuição.', 'relotação.', 'readaptação.'], a: 2, e: 'Art. 55: RELOTAÇÃO, feita ex officio por portaria, no interesse da administração, mantidas as atribuições do cargo. O Estatuto não usa "remoção" nem "redistribuição" (termos da Lei 8.112).', src: 'LC 146/2011 (Estatuto)' },
    { t: 'leg', q: 'Cessão de servidor, pelo art. 56 da LC 146/2011, é o afastamento para outro órgão (entidade de classe, União, Estado, DF ou Município) que:', o: ['independe da vontade do servidor.', 'exige anuência do servidor e concordância dos titulares dos dois Poderes/órgãos, podendo ser com ou sem ônus para o cedente.', 'só pode ocorrer após 10 anos de serviço.', 'é vedada durante o estágio probatório.'], a: 1, e: 'Art. 56 e §§. Sem ônus: quando o servidor exerce cargo em comissão no cessionário. É autorizada no estágio probatório, suspendendo-o se a função for diversa (§3º).', src: 'LC 146/2011 (Estatuto)' },
    { t: 'leg', q: 'A diferença entre vencimento e remuneração é:', o: ['vencimento é a retribuição pelo exercício do cargo, com valor fixado em lei; remuneração é o vencimento acrescido das vantagens pecuniárias permanentes.', 'são sinônimos.', 'remuneração é só para comissionados.', 'vencimento inclui diárias.'], a: 0, e: 'Vencimento (básico) + vantagens (adicionais, gratificações) = remuneração.' },
    { t: 'leg', q: 'As diárias e as indenizações de transporte são:', o: ['vantagens de natureza indenizatória, que não se incorporam ao vencimento.', 'parte do vencimento básico.', 'adicionais por tempo de serviço.', 'gratificações permanentes.'], a: 0, e: 'Indenizações (ajuda de custo, diárias, transporte) ressarcem despesas e não se incorporam.' },
    { t: 'leg', q: 'Segundo o edital do SSPREV (item 1.9), o adicional por tempo de serviço (quinquênio) é de:', o: ['1% a cada ano.', '5% a cada 5 anos.', '10% a cada 10 anos.', '20% aos 20 anos.'], a: 1, e: 'Quinquênio de 5%, além da sexta-parte aos 20 anos e licença-prêmio de 90 dias a cada 5 anos. Confira os artigos na LC 146/2011.' },
    { t: 'leg', q: 'A "sexta-parte" dos vencimentos, benefício tradicional dos servidores paulistas, é concedida, segundo o edital do SSPREV, após:', o: ['5 anos de serviço.', '10 anos de serviço.', '20 anos de serviço.', '35 anos de serviço.'], a: 2, e: 'Sexta-parte aos 20 anos de efetivo exercício (item 1.9 do edital).' },
    { t: 'leg', q: 'Licença-prêmio por assiduidade, conforme resumido no edital do SSPREV:', o: ['30 dias a cada 2 anos.', '90 dias a cada 5 anos de efetivo exercício.', '60 dias a cada 10 anos.', '15 dias por ano.'], a: 1, e: 'Item 1.9 do edital. Verifique no Estatuto as condições de perda do direito (faltas, penalidades).' },
    { t: 'leg', q: 'A licença para tratar de interesses particulares, pela LC 146/2011:', o: ['é remunerada.', 'é concedida sem remuneração, a critério da Administração, ao efetivo que não esteja em estágio probatório, por até 3 anos, uma única vez, podendo ser interrompida a pedido ou no interesse do serviço.', 'é obrigatória.', 'conta como efetivo exercício para todos os efeitos.'], a: 1, e: 'Art. 169 e §§. Durante a licença fica suspenso o efetivo exercício para todos os efeitos (§4º).', src: 'LC 146/2011 (Estatuto)' },
    { t: 'leg', q: 'O direito de petição assegura ao servidor:', o: ['requerer aos Poderes Públicos em defesa de direito ou interesse legítimo, com prazos para recurso e para a Administração decidir.', 'faltar ao trabalho sem justificativa.', 'receber salário em dobro.', 'não ser punido.'], a: 0, e: 'Marque no Estatuto os prazos de recurso e de prescrição (ex.: 5 anos para demissão/cassação, 120 dias para suspensão, 180 dias para advertência no modelo federal).' },
    { t: 'leg', q: 'São deveres do servidor, tipicamente:', o: ['exercer com zelo e dedicação as atribuições, ser leal às instituições, observar as normas, cumprir ordens superiores (exceto quando manifestamente ilegais), atender o público com urbanidade e guardar sigilo sobre assuntos da repartição.', 'cumprir qualquer ordem, mesmo ilegal.', 'valer-se do cargo em proveito próprio.', 'promover manifestações de apreço no recinto.'], a: 0, e: 'Deveres × proibições: ordem manifestamente ilegal NÃO deve ser cumprida.' },
    { t: 'leg', q: 'É PROIBIDO ao servidor, segundo os estatutos:', o: ['tratar o público com urbanidade.', 'ausentar-se do serviço sem autorização, retirar documentos da repartição sem prévia anuência, recusar fé a documentos públicos e exercer comércio incompatível com o cargo.', 'representar contra ilegalidade.', 'guardar sigilo.'], a: 1, e: 'Rol de proibições (modelo Lei 8.112, art. 117).' },
    { t: 'leg', q: 'A acumulação remunerada de cargos públicos é:', o: ['livre.', 'vedada, salvo as hipóteses constitucionais (2 de professor; 1 de professor + 1 técnico/científico; 2 privativos de profissionais de saúde regulamentadas), sempre com compatibilidade de horários.', 'permitida para até três cargos.', 'permitida apenas para comissionados.'], a: 1, e: 'CF art. 37, XVI e XVII. A proibição alcança autarquias, fundações, empresas públicas e sociedades de economia mista.' },
    { t: 'leg', q: 'A penalidade de ADVERTÊNCIA é aplicada, em regra:', o: ['por escrito, nos casos de violação de proibições leves e inobservância de dever funcional que não justifique penalidade mais grave.', 'verbalmente.', 'somente após processo administrativo com 60 dias.', 'com desconto de 30 dias de vencimento.'], a: 0, e: 'Advertência: escrita; suspensão: até 90 dias (modelo federal); demissão: infrações graves.' },
    { t: 'leg', q: 'Para fins de reincidência disciplinar, a LC 146/2011 considera reincidente o servidor que cometer nova infração no período de:', o: ['1 ano.', '2 anos.', '5 anos contados da publicação da decisão definitiva, exceto se a punição anterior foi advertência.', '10 anos.'], a: 2, e: 'Art. 217, §3º. A reincidência de falta punida com advertência leva à suspensão (caput).', src: 'LC 146/2011 (Estatuto)' },
    { t: 'leg', q: 'A SINDICÂNCIA tem por finalidade:', o: ['apurar preliminarmente irregularidade, podendo resultar em arquivamento, aplicação de penalidade leve (advertência ou suspensão curta) ou instauração de processo administrativo disciplinar.', 'demitir diretamente o servidor.', 'julgar o Prefeito.', 'substituir o Tribunal de Contas.'], a: 0, e: 'Sindicância: preliminar/sumária. PAD: obrigatório para penalidades graves, com comissão, instrução, defesa e julgamento.' },
    { t: 'leg', q: 'As fases do processo administrativo disciplinar (PAD) são, em regra:', o: ['instauração (portaria), inquérito administrativo (instrução, defesa e relatório) e julgamento.', 'denúncia, prisão e demissão.', 'apenas julgamento.', 'sindicância e demissão.'], a: 0, e: 'Modelo da Lei 8.112, art. 151. Marque na LC 146/2011 os prazos de conclusão e de prorrogação.' },
    { t: 'leg', q: 'A responsabilidade CIVIL do servidor:', o: ['decorre de ato omissivo ou comissivo, doloso ou culposo, que resulte em prejuízo ao erário ou a terceiros, cabendo ao Estado ação regressiva.', 'só existe se houver crime.', 'é sempre do Município, nunca do servidor.', 'depende de lei municipal específica.'], a: 0, e: 'CF art. 37, §6º: o Estado responde objetivamente e tem direito de regresso contra o servidor em caso de dolo ou culpa.' },
    { t: 'leg', q: 'A absolvição criminal do servidor afasta a responsabilidade administrativa quando:', o: ['sempre.', 'negar a existência do fato ou a sua autoria.', 'for por falta de provas.', 'nunca.'], a: 1, e: 'Independência das instâncias, com exceção: absolvição penal por inexistência do fato ou negativa de autoria repercute na esfera administrativa.' },
    { t: 'leg', q: 'A Lei Orgânica do Município é:', o: ['a "constituição" do município, elaborada pela Câmara Municipal, que organiza os Poderes locais, as competências, as finanças e os servidores, respeitadas a CF e a Constituição Estadual.', 'uma lei federal.', 'um decreto do Prefeito.', 'o regimento interno da Câmara.'], a: 0, e: 'CF art. 29.' },
    { t: 'leg', q: 'Compete privativamente ao Município, segundo a CF (art. 30):', o: ['legislar sobre assuntos de interesse local; instituir e arrecadar seus tributos; organizar os serviços públicos de interesse local, inclusive o transporte coletivo; manter programas de educação infantil e ensino fundamental com cooperação da União e do Estado.', 'legislar sobre direito penal.', 'emitir moeda.', 'manter relações com Estados estrangeiros.'], a: 0, e: 'Art. 30 da CF.' },
    { t: 'leg', q: 'Zelar pela saúde pública, proteger o meio ambiente e promover programas de habitação são competências:', o: ['exclusivas da União.', 'comuns da União, dos Estados, do Distrito Federal e dos Municípios.', 'privativas dos Municípios.', 'privativas dos Estados.'], a: 1, e: 'CF art. 23 (competência comum, material/administrativa).' },
    { t: 'leg', q: 'Legislar sobre proteção ao patrimônio histórico, cultural, artístico, turístico e paisagístico é competência:', o: ['privativa da União.', 'concorrente da União, dos Estados e do Distrito Federal (cabendo ao Município suplementar no interesse local).', 'exclusiva dos Municípios.', 'exclusiva dos Estados.'], a: 1, e: 'CF art. 24, VII. Questão do Instituto Mais (IPMO 2025).', src: 'Instituto Mais · IPMO 2025 (adaptada)' },
    { t: 'leg', q: 'O servidor público municipal investido no mandato de Prefeito:', o: ['acumula as duas remunerações.', 'será afastado do cargo, emprego ou função, sendo-lhe facultado optar pela sua remuneração.', 'perde o cargo efetivo.', 'continua em exercício no cargo.'], a: 1, e: 'CF art. 38, I. Questão do Instituto Mais (IPMO 2025).', src: 'Instituto Mais · IPMO 2025 (adaptada)' },
    { t: 'leg', q: 'O número de vereadores de um município é:', o: ['livre, definido pelo Prefeito.', 'proporcional à população, dentro dos limites mínimos e máximos fixados pela CF (art. 29, IV), definido na Lei Orgânica.', 'sempre 9.', 'definido pela Assembleia Legislativa.'], a: 1, e: 'Para municípios de até 15 mil habitantes, 9 vereadores; a tabela do art. 29, IV, vai até 55.' },
    { t: 'leg', q: 'O subsídio dos vereadores é fixado:', o: ['pela Câmara Municipal, em cada legislatura para a subsequente, observados os limites da CF (percentuais do subsídio dos deputados estaduais e o limite de 5% da receita do município para a folha da Câmara).', 'pelo Prefeito.', 'pelo Tribunal de Contas.', 'por plebiscito.'], a: 0, e: 'CF art. 29, VI e VII.' },
    { t: 'leg', q: 'O processo legislativo municipal compreende a elaboração de:', o: ['emendas à Lei Orgânica, leis complementares, leis ordinárias, decretos legislativos e resoluções.', 'apenas leis ordinárias.', 'medidas provisórias federais.', 'portarias.'], a: 0, e: 'Espelha o art. 59 da CF, no que couber. Decretos legislativos e resoluções são da competência exclusiva da Câmara.' },
    { t: 'leg', q: 'Aprovado um projeto de lei pela Câmara, o Prefeito pode:', o: ['sancioná-lo ou vetá-lo, total ou parcialmente, no prazo previsto na Lei Orgânica (normalmente 15 dias úteis), por inconstitucionalidade ou contrariedade ao interesse público, cabendo à Câmara apreciar o veto.', 'alterá-lo livremente.', 'engavetá-lo.', 'submetê-lo ao Tribunal de Contas.'], a: 0, e: 'Modelo da CF art. 66. Marque na Lei Orgânica os prazos de sanção/veto e de apreciação do veto e o quórum para derrubá-lo (geralmente maioria absoluta).' },
    { t: 'leg', q: 'São de iniciativa privativa do Prefeito os projetos de lei que:', o: ['criem cargos, funções ou empregos na administração direta e autárquica ou aumentem sua remuneração; disponham sobre servidores e seu regime jurídico; e sobre a organização administrativa.', 'tratem de nomes de ruas.', 'concedam títulos honoríficos.', 'alterem o regimento da Câmara.'], a: 0, e: 'Simetria com a CF art. 61, §1º. Emendas parlamentares não podem aumentar despesa nesses projetos.' },
    { t: 'leg', q: 'Pela Lei Orgânica de São Sebastião, o Prefeito encaminha ao Tribunal de Contas do Estado sua prestação de contas, a da Mesa da Câmara e os balanços do exercício findo até:', o: ['31 de janeiro.', '31 de março de cada ano.', '30 de junho.', '31 de dezembro.'], a: 1, e: 'Art. 69, XVIII. A Mesa envia ao Prefeito as contas da Câmara até 1º de março (art. 22, VII). As contas são julgadas pela Câmara (art. 8º, VIII) com parecer do TCE (art. 54, §1º).', src: 'Lei Orgânica de São Sebastião' },
    { t: 'leg', q: 'Em caso de impedimento do Prefeito e do Vice-Prefeito ou vacância de ambos os cargos no ÚLTIMO ano do período governamental, assume:', o: ['o Secretário de Finanças.', 'o Presidente da Câmara Municipal, que completa o período.', 'o Juiz da comarca.', 'o Governador.'], a: 1, e: 'Art. 62 da Lei Orgânica. Nos três primeiros anos, faz-se eleição 90 dias após aberta a última vaga (art. 61).', src: 'Lei Orgânica de São Sebastião' },
    { t: 'leg', q: 'Quanto às finanças, a Lei Orgânica, em harmonia com a CF, determina que o município:', o: ['elabore PPA, LDO e LOA, de iniciativa do Prefeito, aprovadas pela Câmara, e aplique percentuais mínimos em educação (25% da receita de impostos) e saúde (15%).', 'não precise de orçamento.', 'aplique 50% em obras.', 'dependa de aprovação do Estado para gastar.'], a: 0, e: 'CF arts. 165, 212 e 198, §2º, III (c/c ADCT e LC 141/2012).' },
    { t: 'leg', q: 'Entre os tributos de competência municipal estão:', o: ['IPTU, ISS, ITBI, taxas (pelo poder de polícia e por serviços), contribuição de melhoria e contribuição para custeio da iluminação pública (COSIP).', 'ICMS e IPVA.', 'IR e IPI.', 'ITCMD.'], a: 0, e: 'CF arts. 145, 149-A e 156.' },
    { t: 'leg', q: 'Os bens imóveis do município podem ser alienados:', o: ['livremente pelo Prefeito.', 'mediante autorização legislativa, avaliação prévia e licitação (concorrência ou leilão), ressalvadas as exceções legais.', 'por decisão do Tribunal de Contas.', 'nunca.'], a: 1, e: 'Lei 14.133, art. 76, I. Em geral, a Lei Orgânica repete a exigência de autorização da Câmara.' },
    { t: 'leg', q: 'Conforme o edital do SSPREV (item 13.16), considera-se para a prova a legislação:', o: ['vigente na data da prova.', 'vigente até a data de publicação do edital (17/08/2026), inclusive alterações até então.', 'em vigor em 1º/01/2026.', 'apenas a original, sem alterações.'], a: 1, e: 'Alterações publicadas após 17/08/2026 não serão cobradas.' },
  ];

  // Anexa ao banco principal com ids sequenciais estáveis (continua após o último id de questions.js)
  const base = window.QUESTOES || [];
  const start = base.length;
  Q2.forEach((q, i) => base.push({ id: 'q' + (start + i), ...q }));
  window.QUESTOES = base;
})();
